noise.uniform:
struct NoiseU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    scale: f32, gain: f32, pad0: f32, pad1: f32,
    k: vec4f,
}
@group(0) @binding(0) var<uniform> u: NoiseU;

noise.core:
// ═══════════════════════════════════════════════════════════════════════════
//  NOISE TABLE  ·  a taxonomy of the functions used to compose procedural
//  textures, one WGSL function per cell.
//
//  Every cell is  fn n_<name>(p: vec2f, t: f32, k: vec4f) -> f32  returning a
//  value in 0..1. p is the centered, aspect-corrected, globally scaled domain
//  (about ±2 across a cell), t the animated phase, k the four cell knobs (0..1).
//
//  References (the kit is assembled from these, not invented):
//    hash        Jarzynski & Olano, "Hash Functions for GPU Rendering", JCGT 2020 (pcg3d)
//    IGN         Jorge Jimenez, "Next Generation Post Processing in Call of Duty", 2014
//    value/perlin Perlin 1985/2002 (quintic fade), gradients from the hash
//    simplex     Gustavson / McEwan et al., webgl-noise (MIT), snoise 2D
//    worley      Worley, "A Cellular Texture Basis Function", SIGGRAPH 1996
//    fbm/warp    Quilez, "fbm" and "Domain warping" articles (iquilezles.org)
//    voronoise   Quilez, "Voronoise" (iquilezles.org)
//    smooth voronoi  Quilez, "Smooth Voronoi"
//    sdf         Quilez, "2D distance functions"
//    gabor       Lagae et al., "Procedural Noise using Sparse Gabor Convolution", 2009
//    phasor      Tricard et al., "Procedural Phasor Noise", SIGGRAPH 2019
//    spot/sparse Lewis, "Algorithms for Solid Noise Synthesis", 1989 (sparse convolution)
//    sum of sines Finch, "Effective Water Simulation", GPU Gems 1
// ═══════════════════════════════════════════════════════════════════════════

const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;

// ───────────────────────────────────────────────────────────── hashing
fn pcg3d(vin: vec3u) -> vec3u {
    var v = vin * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> vec3u(16u);
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return v;
}
fn h3(p: vec3i, seed: u32) -> vec3f {
    let q = pcg3d(vec3u(p + vec3i(32768)) ^ vec3u(seed, seed * 3u + 1u, seed * 7u + 5u));
    return vec3f(q) * (1.0 / 4294967295.0);
}
fn h21(p: vec2i, seed: u32) -> f32 { return h3(vec3i(p, 0), seed).x; }
fn h22(p: vec2i, seed: u32) -> vec2f { return h3(vec3i(p, 0), seed).xy; }
fn h11(x: i32, seed: u32) -> f32 { return h3(vec3i(x, 0, 0), seed).x; }
fn fade(t: vec2f) -> vec2f { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
fn fade3(t: vec3f) -> vec3f { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
fn rot2(a: f32) -> mat2x2f { let c = cos(a); let s = sin(a); return mat2x2f(c, s, -s, c); }

// ───────────────────────────────────────────────────────────── lattice noises
// Value noise: random values at lattice points, quintic-smoothed bilinear blend.
fn vnoise(p: vec2f, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fade(fract(p));
    let a = h21(i, seed); let b = h21(i + vec2i(1, 0), seed);
    let c = h21(i + vec2i(0, 1), seed); let d = h21(i + vec2i(1, 1), seed);
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
// Cubic value noise: 4x4 Catmull-Rom instead of quintic bilinear.
fn cubic4(a: f32, b: f32, c: f32, d: f32, t: f32) -> f32 {
    return b + 0.5 * t * (c - a + t * (2.0 * a - 5.0 * b + 4.0 * c - d + t * (3.0 * (b - c) + d - a)));
}
fn vnoise_cubic(p: vec2f, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p);
    var rows: array<f32, 4>;
    for (var y: i32 = -1; y <= 2; y++) {
        rows[y + 1] = cubic4(h21(i + vec2i(-1, y), seed), h21(i + vec2i(0, y), seed), h21(i + vec2i(1, y), seed), h21(i + vec2i(2, y), seed), f.x);
    }
    return clamp(cubic4(rows[0], rows[1], rows[2], rows[3], f.y), 0.0, 1.0);
}
// Perlin gradient noise, 2D: unit gradients from the hash, dot with the offset, quintic blend. Returns ~-1..1.
fn grad2(i: vec2i, seed: u32) -> vec2f { let a = h21(i, seed) * TAU; return vec2f(cos(a), sin(a)); }
fn pnoise(p: vec2f, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p); let u = fade(f);
    let a = dot(grad2(i, seed), f); let b = dot(grad2(i + vec2i(1, 0), seed), f - vec2f(1.0, 0.0));
    let c = dot(grad2(i + vec2i(0, 1), seed), f - vec2f(0.0, 1.0)); let d = dot(grad2(i + vec2i(1, 1), seed), f - vec2f(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.414;
}
// Periodic Perlin: the lattice wraps every `period` cells, so the texture tiles.
fn pnoise_tiled(p: vec2f, period: vec2i, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p); let u = fade(f);
    let i00 = ((i % period) + period) % period; let i11 = (((i + 1) % period) + period) % period;
    let a = dot(grad2(i00, seed), f); let b = dot(grad2(vec2i(i11.x, i00.y), seed), f - vec2f(1.0, 0.0));
    let c = dot(grad2(vec2i(i00.x, i11.y), seed), f - vec2f(0.0, 1.0)); let d = dot(grad2(i11, seed), f - vec2f(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.414;
}
// Perlin 3D, for animated slices: random unit gradients on the sphere.
fn grad3(i: vec3i, seed: u32) -> vec3f {
    let r = h3(i, seed); let z = r.x * 2.0 - 1.0; let a = r.y * TAU; let s = sqrt(max(1.0 - z * z, 0.0));
    return vec3f(s * cos(a), s * sin(a), z);
}
fn pnoise3(p: vec3f, seed: u32) -> f32 {
    let i = vec3i(floor(p)); let f = fract(p); let u = fade3(f);
    var v: array<f32, 8>;
    for (var n: i32 = 0; n < 8; n++) {
        let o = vec3i(n & 1, (n >> 1u) & 1, (n >> 2u) & 1);
        v[n] = dot(grad3(i + o, seed), f - vec3f(o));
    }
    return mix(mix(mix(v[0], v[1], u.x), mix(v[2], v[3], u.x), u.y), mix(mix(v[4], v[5], u.x), mix(v[6], v[7], u.x), u.y), u.z) * 1.15;
}
// Simplex noise 2D (Gustavson / McEwan, webgl-noise). Returns ~-1..1.
fn mod289v3(x: vec3f) -> vec3f { return x - floor(x * (1.0 / 289.0)) * 289.0; }
fn mod289v2(x: vec2f) -> vec2f { return x - floor(x * (1.0 / 289.0)) * 289.0; }
fn permute3(x: vec3f) -> vec3f { return mod289v3(((x * 34.0) + 1.0) * x); }
fn snoise(v: vec2f) -> f32 {
    let C = vec4f(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    var i = floor(v + dot(v, C.yy));
    let x0 = v - i + dot(i, C.xx);
    var i1 = vec2f(0.0, 1.0);
    if (x0.x > x0.y) { i1 = vec2f(1.0, 0.0); }
    var x12 = x0.xyxy + C.xxzz;
    x12 = vec4f(x12.xy - i1, x12.zw);
    i = mod289v2(i);
    let p = permute3(permute3(i.y + vec3f(0.0, i1.y, 1.0)) + i.x + vec3f(0.0, i1.x, 1.0));
    var m = max(vec3f(0.5) - vec3f(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), vec3f(0.0));
    m = m * m; m = m * m;
    let x = 2.0 * fract(p * C.www) - 1.0;
    let h = abs(x) - 0.5;
    let ox = floor(x + 0.5);
    let a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
    let g = vec3f(a0.x * x0.x + h.x * x0.y, a0.yz * x12.xz + h.yz * x12.yw);
    return 130.0 * dot(m, g);
}

// ───────────────────────────────────────────────────────────── fractal sums
fn fbm(pin: vec2f, oct: i32, lac: f32, gain: f32, seed: u32) -> f32 {
    var p = pin; var a = 0.5; var s = 0.0; var nrm = 0.0;
    for (var i: i32 = 0; i < 8; i++) {
        if (i >= oct) { break; }
        s += a * pnoise(p, seed + u32(i)); nrm += a; a *= gain; p = rot2(0.5) * p * lac;
    }
    return s / nrm;                 // ~-1..1
}
fn fbm01(p: vec2f, oct: i32, lac: f32, gain: f32, seed: u32) -> f32 { return 0.5 + 0.5 * fbm(p, oct, lac, gain, seed); }
fn turbulence(pin: vec2f, oct: i32, lac: f32, gain: f32, seed: u32) -> f32 {
    var p = pin; var a = 0.5; var s = 0.0; var nrm = 0.0;
    for (var i: i32 = 0; i < 8; i++) {
        if (i >= oct) { break; }
        s += a * abs(pnoise(p, seed + u32(i))); nrm += a; a *= gain; p = rot2(0.5) * p * lac;
    }
    return s / nrm;
}
fn ridged(pin: vec2f, oct: i32, lac: f32, gain: f32, sharp: f32, seed: u32) -> f32 {
    var p = pin; var a = 0.5; var s = 0.0; var nrm = 0.0; var w = 1.0;
    for (var i: i32 = 0; i < 8; i++) {
        if (i >= oct) { break; }
        var r = 1.0 - abs(pnoise(p, seed + u32(i))); r = pow(r, sharp) * w; w = clamp(r * 2.0, 0.0, 1.0);
        s += a * r; nrm += a; a *= gain; p = rot2(0.5) * p * lac;
    }
    return s / nrm;
}

// ───────────────────────────────────────────────────────────── cellular
// Worley: nearest and second-nearest jittered feature points in the 3x3 neighborhood.
// metric 0 euclidean, 1 manhattan, 2 chebyshev. Returns (F1, F2, cell id).
fn worley(p: vec2f, jitter: f32, metric: i32, seed: u32) -> vec3f {
    let i = vec2i(floor(p)); let f = fract(p);
    var f1 = 8.0; var f2 = 8.0; var id = 0.0;
    for (var y: i32 = -1; y <= 1; y++) {
        for (var x: i32 = -1; x <= 1; x++) {
            let o = vec2i(x, y);
            let r = vec2f(o) + mix(vec2f(0.5), h22(i + o, seed), jitter) - f;
            var d = dot(r, r);
            if (metric == 1) { let m = abs(r.x) + abs(r.y); d = m * m; }
            if (metric == 2) { let m = max(abs(r.x), abs(r.y)); d = m * m; }
            if (d < f1) { f2 = f1; f1 = d; id = h21(i + o, seed + 9u); }
            else if (d < f2) { f2 = d; }
        }
    }
    return vec3f(sqrt(f1), sqrt(f2), id);
}
// Smooth Voronoi (Quilez): exponential soft-min of the distances, no cell edges.
fn worley_smooth(p: vec2f, k: f32, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p); var res = 0.0;
    for (var y: i32 = -1; y <= 1; y++) {
        for (var x: i32 = -1; x <= 1; x++) {
            let o = vec2i(x, y); let r = vec2f(o) + h22(i + o, seed) - f;
            res += exp2(-k * length(r));
        }
    }
    return -log2(res) / k;
}
// Voronoise (Quilez): one function that morphs between value noise and Voronoi cells.
fn voronoise(p: vec2f, u: f32, v: f32, seed: u32) -> f32 {
    let kk = 1.0 + 63.0 * pow(1.0 - v, 6.0);
    let i = vec2i(floor(p)); let f = fract(p);
    var a = vec2f(0.0);
    for (var y: i32 = -2; y <= 2; y++) {
        for (var x: i32 = -2; x <= 2; x++) {
            let g = vec2f(f32(x), f32(y));
            let o = h3(vec3i(i + vec2i(x, y), 0), seed) * vec3f(u, u, 1.0);
            let d = g - f + o.xy;
            let w = pow(1.0 - smoothstep(0.0, 1.414, length(d)), kk);
            a += vec2f(o.z * w, w);
        }
    }
    return a.x / a.y;
}

// ───────────────────────────────────────────────────────────── distance fields (Quilez)
fn sdCircle(p: vec2f, r: f32) -> f32 { return length(p) - r; }
fn sdBox(p: vec2f, b: vec2f) -> f32 { let d = abs(p) - b; return length(max(d, vec2f(0.0))) + min(max(d.x, d.y), 0.0); }
fn sdSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 { let pa = p - a; let ba = b - a; let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0); return length(pa - ba * h); }
fn sdNgon(p: vec2f, r: f32, n: f32) -> f32 {
    let an = PI / n; let a = atan2(p.y, p.x);
    let b = (((a % (2.0 * an)) + 2.0 * an) % (2.0 * an)) - an;
    return length(p) * cos(b) - r;
}
fn sdStar5(pin: vec2f, r: f32, rf: f32) -> f32 {
    let k1 = vec2f(0.809016994375, -0.587785252292); let k2 = vec2f(-k1.x, k1.y);
    var p = vec2f(abs(pin.x), pin.y);
    p -= 2.0 * max(dot(k1, p), 0.0) * k1;
    p -= 2.0 * max(dot(k2, p), 0.0) * k2;
    p.x = abs(p.x); p.y -= r;
    let ba = rf * vec2f(-k1.y, k1.x) - vec2f(0.0, 1.0);
    let h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
    return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
}
fn fill(d: f32, aa: f32) -> f32 { return 1.0 - smoothstep(-aa, aa, d); }

// ───────────────────────────────────────────────────────────── kernels
// One Gabor kernel: gaussian envelope times a cosine grating (Lagae 2009).
fn gabor(p: vec2f, a: f32, f0: f32, w0: f32) -> f32 {
    return exp(-PI * a * a * dot(p, p)) * cos(TAU * f0 * (p.x * cos(w0) + p.y * sin(w0)));
}
// Sparse Gabor convolution: jittered kernels in each of 3x3 cells; iso in [0,1] blends isotropic vs one orientation.
fn gabor_noise(p: vec2f, a: f32, f0: f32, w0: f32, iso: f32, per: i32, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p); var s = 0.0;
    for (var y: i32 = -1; y <= 1; y++) {
        for (var x: i32 = -1; x <= 1; x++) {
            let o = vec2i(x, y);
            for (var n: i32 = 0; n < 4; n++) {
                if (n >= per) { break; }
                let r = h3(vec3i(i + o, n), seed);
                let q = f - vec2f(o) - r.xy;
                let w = mix(w0, r.z * TAU, iso);
                s += (h3(vec3i(i + o, n + 8), seed).x * 2.0 - 1.0) * gabor(q, a, f0, w);
            }
        }
    }
    return s;
}
// Phasor noise (Tricard 2019): track the kernels as complex numbers, output the phase → strict oscillation.
fn phasor(p: vec2f, a: f32, f0: f32, w0: f32, iso: f32, seed: u32) -> vec2f {
    let i = vec2i(floor(p)); let f = fract(p); var z = vec2f(0.0);
    for (var y: i32 = -1; y <= 1; y++) {
        for (var x: i32 = -1; x <= 1; x++) {
            let o = vec2i(x, y);
            for (var n: i32 = 0; n < 3; n++) {
                let r = h3(vec3i(i + o, n), seed);
                let q = f - vec2f(o) - r.xy;
                let w = mix(w0, r.z * TAU, iso);
                let env = exp(-PI * a * a * dot(q, q));
                let ph = TAU * f0 * (q.x * cos(w) + q.y * sin(w));
                z += env * vec2f(cos(ph), sin(ph));
            }
        }
    }
    return z;
}

// ═══════════════════════════════════════════════════════════════ THE CELLS
// knobs: k.x k.y k.z k.w, each 0..1; the meaning is named in the table.


// bayer: the 8x8 ordered-dither matrix thresholding a moving gradient.
const BAYER8 = array<u32, 64>(0u,32u,8u,40u,2u,34u,10u,42u, 48u,16u,56u,24u,50u,18u,58u,26u, 12u,44u,4u,36u,14u,46u,6u,38u, 60u,28u,52u,20u,62u,30u,54u,22u,
    3u,35u,11u,43u,1u,33u,9u,41u, 51u,19u,59u,27u,49u,17u,57u,25u, 15u,47u,7u,39u,13u,45u,5u,37u, 63u,31u,55u,23u,61u,29u,53u,21u);




























































































// The palette rail: ink → tone → cream, applied after the contrast gain.
fn present(v0: f32) -> vec4f {
    let v = clamp((clamp(v0, 0.0, 1.0) - 0.5) * u.gain + 0.5, 0.0, 1.0);
    let lo = mix(u.ink.rgb, u.tone.rgb, smoothstep(0.0, 0.62, v));
    let hi = mix(lo, u.cream.rgb, smoothstep(0.62, 1.0, v));
    return vec4f(hi, 1.0);
}
fn domain(fp: vec2f) -> vec2f {
    let pos = fp / u.pixelScale;
    return (pos - 0.5 * u.size) / max(min(u.size.x, u.size.y), 1.0) * 3.0 * u.scale;
}

entries.white:
// —— hash ————————————————————————————————————————————————————————————————
// white: an independent random value per lattice cell of the current scale.
fn n_white(p: vec2f, t: f32, k: vec4f) -> f32 {
    let cells = mix(8.0, 80.0, k.x);
    let frame = floor(t * mix(0.0, 24.0, k.y));
    return h21(vec2i(floor(p * cells)), 1u + u32(frame));
}

entries.bayer:
fn n_bayer(p: vec2f, t: f32, k: vec4f) -> f32 {
    let cells = mix(8.0, 64.0, k.x);
    let c = vec2i(floor(p * cells));
    let thr = (f32(BAYER8[(c.y & 7) * 8 + (c.x & 7)]) + 0.5) / 64.0;
    let g = 0.5 + 0.5 * sin(p.x * mix(1.0, 4.0, k.z) + t * k.y);
    return select(0.0, 1.0, g > thr);
}

entries.ign:
// ign: interleaved gradient noise (Jimenez), the screen-space dither used in games.
fn n_ign(p: vec2f, t: f32, k: vec4f) -> f32 {
    let px = floor(p * mix(20.0, 160.0, k.x)) + floor(t * 6.0 * k.y);
    return fract(52.9829189 * fract(dot(px, vec2f(0.06711056, 0.00583715))));
}

entries.hash_cells:
// cells: a random grey per grid cell, with random cell aspect.
fn n_hash_cells(p: vec2f, t: f32, k: vec4f) -> f32 {
    let g = vec2f(mix(2.0, 24.0, k.x), mix(2.0, 24.0, k.y));
    let i = vec2i(floor(p * g + vec2f(t * k.z, 0.0)));
    return h21(i, 3u);
}

entries.sparkle:
// sparkle: a hashed threshold that twinkles by sampling a second hash on time.
fn n_sparkle(p: vec2f, t: f32, k: vec4f) -> f32 {
    let i = vec2i(floor(p * mix(10.0, 60.0, k.x)));
    let r = h3(vec3i(i, 0), 5u);
    let ph = fract(t * mix(0.2, 2.0, k.y) + r.y);
    let on = step(1.0 - mix(0.02, 0.4, k.z), r.x);
    return on * (0.5 + 0.5 * sin(ph * TAU)) * mix(0.5, 1.0, r.z);
}

entries.dust:
// dust: one jittered dot per cell, radius from the hash.
fn n_dust(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(4.0, 24.0, k.x) + vec2f(0.0, t * 0.4 * k.w);
    let i = vec2i(floor(q)); let f = fract(q); var v = 0.0;
    for (var y: i32 = -1; y <= 1; y++) { for (var x: i32 = -1; x <= 1; x++) {
        let o = vec2i(x, y); let r = h3(vec3i(i + o, 0), 7u);
        let d = length(f - vec2f(o) - r.xy);
        v = max(v, fill(d - mix(0.05, 0.4, k.y) * r.z, mix(0.01, 0.3, k.z)));
    } }
    return v;
}

entries.r2:
// r2: Roberts' R2 quasi-random sequence — evenly spread points from a plastic-constant recurrence.
fn n_r2(p: vec2f, t: f32, k: vec4f) -> f32 {
    let n = i32(mix(10.0, 200.0, k.x)); var v = 0.0; let rad = mix(0.01, 0.08, k.y);
    let q = fract(p * 0.25 + 0.5);
    for (var i: i32 = 0; i < 400; i++) { if (i >= n) { break; }
        let fi = f32(i) + t * 2.0 * k.z;
        let pt = fract(vec2f(0.7548776662, 0.5698402910) * fi + 0.5);
        var d = abs(q - pt); d = min(d, 1.0 - d);
        v = max(v, fill(length(d) - rad, 0.005)); }
    return v;
}

entries.tiled:
// tiled: periodic gradient noise; the outline shows the tile that repeats.
fn n_tiled(p: vec2f, t: f32, k: vec4f) -> f32 {
    let per = i32(mix(2.0, 8.0, k.x));
    let q = (p + vec2f(t * 0.2 * k.y, 0.0)) * 2.0;
    let v = 0.5 + 0.5 * pnoise_tiled(q, vec2i(per), 19u);
    let cell = fract(q / f32(per)); let edge = min(min(cell.x, 1.0 - cell.x), min(cell.y, 1.0 - cell.y));
    return mix(v, 1.0, k.z * (1.0 - smoothstep(0.0, 0.02, edge)));
}

entries.multifractal:
// multifractal: octaves multiply rather than add, so rough stays rough only where the base is rough.
fn n_multifractal(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(0.5, 6.0, k.x) + vec2f(t * 0.2 * k.w, 0.0); var v = 1.0; var a = 1.0;
    let oct = i32(mix(1.0, 8.0, k.y)); let off = mix(0.4, 1.2, k.z);
    for (var i: i32 = 0; i < 8; i++) { if (i >= oct) { break; }
        v *= (pnoise(q, 37u + u32(i)) * a + off); a *= 0.5; q = rot2(0.5) * q * 2.0; }
    return clamp(v * 0.8, 0.0, 1.0);
}

entries.warp:
// warp: Quilez domain warping, f(p + 4 f(p + 4 f(p))).
fn n_warp(p: vec2f, t: f32, k: vec4f) -> f32 {
    let s = mix(0.5, 4.0, k.x); let amt = mix(0.0, 4.0, k.y); let oct = i32(mix(2.0, 6.0, k.z));
    let q = vec2f(fbm(p * s, oct, 2.0, 0.5, 41u), fbm(p * s + vec2f(5.2, 1.3), oct, 2.0, 0.5, 43u));
    let r = vec2f(fbm(p * s + amt * q + vec2f(1.7, 9.2) + t * 0.1 * k.w, oct, 2.0, 0.5, 47u), fbm(p * s + amt * q + vec2f(8.3, 2.8) + t * 0.08 * k.w, oct, 2.0, 0.5, 53u));
    return fbm01(p * s + amt * r, oct, 2.0, 0.5, 59u);
}

entries.warp_self:
// warp_self: a single noise displaced by its own gradient, iterated — flow-like folds.
fn n_warp_self(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(0.5, 4.0, k.x); let amt = mix(0.0, 1.5, k.y); let n = i32(mix(1.0, 5.0, k.z));
    for (var i: i32 = 0; i < 5; i++) { if (i >= n) { break; }
        let e = 0.01; let v = pnoise(q + t * 0.1 * k.w, 61u);
        let g = vec2f(pnoise(q + vec2f(e, 0.0) + t * 0.1 * k.w, 61u) - v, pnoise(q + vec2f(0.0, e) + t * 0.1 * k.w, 61u) - v) / e;
        q += amt * 0.1 * vec2f(-g.y, g.x); }
    return fbm01(q, 4, 2.0, 0.5, 61u);
}

entries.octave_rotate:
// octave_rotate: fbm whose octaves each rotate with time at their own rate — the swirl in "noise-y" clouds.
fn n_octave_rotate(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(0.5, 5.0, k.x); var a = 0.5; var s = 0.0; var nrm = 0.0; let oct = i32(mix(2.0, 8.0, k.y));
    for (var i: i32 = 0; i < 8; i++) { if (i >= oct) { break; }
        s += a * pnoise(rot2(t * mix(0.0, 0.4, k.z) * f32(i + 1)) * q, 67u + u32(i)); nrm += a; a *= 0.5; q *= 2.0; }
    return 0.5 + 0.5 * s / nrm;
}

entries.fbm_value:
// fbm_value: the same octave sum built on value noise — blockier lows than the gradient version.
fn n_fbm_value(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(0.5, 6.0, k.x) + vec2f(t * 0.2 * k.w, 0.0); var a = 0.5; var s = 0.0; var nrm = 0.0; let oct = i32(mix(1.0, 8.0, k.y));
    for (var i: i32 = 0; i < 8; i++) { if (i >= oct) { break; }
        s += a * vnoise(q, 211u + u32(i)); nrm += a; a *= mix(0.3, 0.8, k.z); q = rot2(0.5) * q * 2.0; }
    return s / nrm;
}

entries.cracks:
// cracks: the Worley edge distance warped by fbm, thresholded thin — dried mud.
fn n_cracks(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 8.0, k.x) + 0.35 * k.y * vec2f(fbm(p * 3.0 + t * 0.05, 3, 2.0, 0.5, 89u), fbm(p * 3.0 + 4.1, 3, 2.0, 0.5, 97u));
    let w = worley(q, 1.0, 0, 101u);
    return 1.0 - smoothstep(0.0, mix(0.02, 0.2, k.z), w.y - w.x);
}

entries.worley_fbm:
// worley_fbm: F1 summed over octaves — the cellular fbm behind scales, foam and lava.
fn n_worley_fbm(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(1.0, 6.0, k.x) + t * 0.2 * k.w; var a = 0.5; var s = 0.0; var nrm = 0.0; let oct = i32(mix(1.0, 5.0, k.y));
    for (var i: i32 = 0; i < 5; i++) { if (i >= oct) { break; }
        s += a * worley(q, k.z, 0, 223u + u32(i)).x; nrm += a; a *= 0.5; q = rot2(0.6) * q * 2.0; }
    return s / nrm;
}

entries.interference:
// interference: two gratings at a small angle → moiré beats.
fn n_interference(p: vec2f, t: f32, k: vec4f) -> f32 {
    let f = mix(10.0, 60.0, k.x); let a = mix(0.0, 0.3, k.y) + 0.02 * sin(t * k.z);
    let s1 = sin(p.x * f); let s2 = sin((rot2(a) * p).x * f);
    return 0.5 + 0.25 * (s1 + s2);
}

entries.hex:
// hex: hexagonal lattice distance, the honeycomb.
fn n_hex(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 10.0, k.x) + vec2f(t * 0.3 * k.z, 0.0);
    let s = vec2f(1.0, 1.7320508); let a = (fract(q / s) - 0.5) * s; let b = (fract(q / s + 0.5) - 0.5) * s;
    var g = a; if (dot(a, a) > dot(b, b)) { g = b; }
    let d = max(abs(g.x) * 0.8660254 + abs(g.y) * 0.5, abs(g.y));
    return smoothstep(mix(0.5, 0.2, k.y), 0.5, d);
}

entries.sum_sines:
// sum of sines: Finch's water — directional sine waves of decreasing size, sharpened by pow.
fn n_sum_sines(p: vec2f, t: f32, k: vec4f) -> f32 {
    var s = 0.0; var amp = 1.0; var f = mix(2.0, 8.0, k.x); var nrm = 0.0;
    for (var i: i32 = 0; i < 6; i++) {
        let d = vec2f(cos(f32(i) * 1.9), sin(f32(i) * 1.9));
        s += amp * pow(0.5 + 0.5 * sin(dot(d, p) * f + t * mix(0.0, 3.0, k.z) * (1.0 + 0.3 * f32(i))), mix(1.0, 4.0, k.y));
        nrm += amp; amp *= 0.6; f *= 1.6;
    }
    return s / nrm;
}

entries.plasma:
// plasma: the demoscene classic — sines of x, y, the sum, and the distance.
fn n_plasma(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 6.0, k.x); let tt = t * mix(0.0, 2.0, k.y);
    let v = sin(q.x + tt) + sin(q.y + tt * 0.7) + sin(q.x + q.y + tt * 1.3) + sin(length(q + vec2f(sin(tt * 0.5), cos(tt * 0.4)) * 2.0) + tt);
    return 0.5 + 0.5 * sin(v * mix(0.5, 3.0, k.z));
}

entries.hatch:
// hatch: two thresholded gratings, the engraver's cross-hatch, density from a noise field.
fn n_hatch(p: vec2f, t: f32, k: vec4f) -> f32 {
    let f = mix(10.0, 60.0, k.x); let dens = fbm01(p * 1.5 + t * 0.1 * k.z, 3, 2.0, 0.5, 227u);
    let a = step(mix(0.2, 0.9, k.y) * dens, 0.5 + 0.5 * sin(p.x * f + p.y * f * 0.3));
    let b = step(mix(0.2, 0.9, k.y) * (dens - 0.3), 0.5 + 0.5 * sin(p.y * f - p.x * f * 0.3));
    return a * b;
}

entries.polar:
// —— domain ——————————————————————————————————————————————————————————————
// polar: fbm sampled in (angle, radius) — rings and spokes.
fn n_polar(p: vec2f, t: f32, k: vec4f) -> f32 {
    let a = atan2(p.y, p.x); let r = length(p);
    return fbm01(vec2f(a * mix(1.0, 6.0, k.x) / PI, r * mix(1.0, 8.0, k.y) - t * 0.4 * k.z), 4, 2.0, 0.5, 103u);
}

entries.logpolar:
// log-polar: the zoom-invariant remap; scrolling the log axis zooms forever.
fn n_logpolar(p: vec2f, t: f32, k: vec4f) -> f32 {
    let a = atan2(p.y, p.x); let r = log(length(p) + 1e-4);
    return fbm01(vec2f(a * mix(1.0, 6.0, k.x) / PI, r * mix(1.0, 4.0, k.y) - t * 0.3 * k.z), 4, 2.0, 0.5, 107u);
}

entries.kaleido:
// kaleidoscope: fold the plane into a wedge, mirror it — n-fold symmetry from any noise.
fn n_kaleido(p: vec2f, t: f32, k: vec4f) -> f32 {
    let n = floor(mix(2.0, 12.0, k.x)); var a = atan2(p.y, p.x) + t * 0.1 * k.z; let r = length(p);
    let w = TAU / n; a = abs(fract(a / w) - 0.5) * w;
    return fbm01(vec2f(cos(a), sin(a)) * r * mix(1.0, 6.0, k.y) + 3.0, 4, 2.0, 0.5, 109u);
}

entries.twist:
// twist: rotate by an angle that grows with radius.
fn n_twist(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = rot2(length(p) * mix(0.0, 6.0, k.x) + t * 0.3 * k.z) * p;
    return smoothstep(0.4, 0.6, 0.5 + 0.5 * sin(q.x * mix(4.0, 30.0, k.y)));
}

entries.zoom_cascade:
// zoom cascade: the same pattern at several scales, blended by a zoom that never ends.
fn n_zoom_cascade(p: vec2f, t: f32, k: vec4f) -> f32 {
    let z = fract(t * mix(0.0, 0.3, k.y)); var s = 0.0; var nrm = 0.0;
    for (var i: i32 = 0; i < 4; i++) {
        let sc = exp2(f32(i) + z) * mix(0.5, 2.0, k.x);
        let w = sin(PI * fract((f32(i) + z) / 4.0));
        s += w * pnoise(p * sc, 113u + u32(i)); nrm += w;
    }
    return 0.5 + 0.5 * s / max(nrm, 1e-3);
}

entries.repeat:
// repeat: domain repetition with a per-tile hashed rotation and offset.
fn n_repeat(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 8.0, k.x); let i = vec2i(floor(q)); let r = h3(vec3i(i, 0), 127u);
    let f = rot2(floor(r.x * 4.0) * PI * 0.5 * k.y) * (fract(q) - 0.5);
    return 1.0 - smoothstep(0.0, mix(0.1, 0.5, k.z), abs(sdCircle(f, 0.3 + 0.1 * sin(t + r.y * TAU))));
}

entries.sinwarp:
// sin-warp: displace the domain by sines before sampling — the marble/curtain warp.
fn n_sinwarp(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 6.0, k.x);
    let w = q + mix(0.0, 1.5, k.y) * vec2f(sin(q.y * 2.0 + t * 0.5 * k.z), sin(q.x * 2.0 - t * 0.4 * k.z));
    return fbm01(w, 4, 2.0, 0.5, 131u);
}

entries.mirror:
// reflect: mirror the domain in a moving line — the symmetric double.
fn n_mirror(p: vec2f, t: f32, k: vec4f) -> f32 {
    let n = vec2f(cos(t * 0.2 * k.z), sin(t * 0.2 * k.z)); var q = p;
    let d = dot(q, n) - mix(-0.6, 0.6, k.y); q -= 2.0 * max(d, 0.0) * n;
    return fbm01(q * mix(1.0, 6.0, k.x) + 7.0, 4, 2.0, 0.5, 137u);
}

entries.edges:
// edges: finite-difference gradient magnitude of fbm — where the slope is.
fn n_edges(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(0.5, 4.0, k.x) + t * 0.1 * k.w; let e = 0.002;
    let v = fbm(q, 4, 2.0, 0.5, 157u);
    let g = vec2f(fbm(q + vec2f(e, 0.0), 4, 2.0, 0.5, 157u) - v, fbm(q + vec2f(0.0, e), 4, 2.0, 0.5, 157u) - v) / e;
    return clamp(length(g) * mix(0.05, 0.6, k.y), 0.0, 1.0);
}

entries.gamma:
// gamma: the same fbm through a power curve and a bias/gain (Schlick) — the response curve as a knob.
fn n_gamma(p: vec2f, t: f32, k: vec4f) -> f32 {
    let v = fbm01(p * mix(0.5, 4.0, k.x) + t * 0.1 * k.w, 4, 2.0, 0.5, 139u);
    let g = mix(0.3, 3.0, k.y); let b = mix(0.2, 0.8, k.z);
    let bias = v / ((1.0 / b - 2.0) * (1.0 - v) + 1.0);
    return pow(clamp(bias, 0.0, 1.0), g);
}

entries.gyroid:
// gyroid: a slice through the triply-periodic minimal surface, sin·cos terms.
fn n_gyroid(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = vec3f(p * mix(2.0, 12.0, k.x), t * mix(0.0, 2.0, k.w));
    let g = dot(sin(q), cos(q.zxy));
    return 1.0 - smoothstep(0.0, mix(0.1, 1.0, k.y), abs(g - mix(-1.0, 1.0, k.z)));
}

entries.spot:
// spot noise: sparse gaussian blobs with random sign (Lewis).
fn n_spot(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 6.0, k.x) + t * 0.15 * k.w; let i = vec2i(floor(q)); let f = fract(q); var s = 0.0;
    let w = mix(0.1, 0.6, k.y); let n = i32(mix(1.0, 4.0, k.z));
    for (var y: i32 = -1; y <= 1; y++) { for (var x: i32 = -1; x <= 1; x++) { for (var m: i32 = 0; m < 4; m++) { if (m >= n) { break; }
        let o = vec2i(x, y); let r = h3(vec3i(i + o, m), 181u); let d = f - vec2f(o) - r.xy;
        s += (r.z * 2.0 - 1.0) * exp(-dot(d, d) / (w * w)); } } }
    return clamp(0.5 + 0.5 * s, 0.0, 1.0);
}

entries.sparse_conv:
// sparse convolution: random-amplitude cosine kernels (Lewis 1989).
fn n_sparse_conv(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(1.0, 6.0, k.x) + t * 0.15 * k.w; let i = vec2i(floor(q)); let f = fract(q); var s = 0.0;
    let R = mix(0.4, 1.0, k.y);
    for (var y: i32 = -1; y <= 1; y++) { for (var x: i32 = -1; x <= 1; x++) { for (var m: i32 = 0; m < 2; m++) {
        let o = vec2i(x, y); let r = h3(vec3i(i + o, m), 191u); let d = length(f - vec2f(o) - r.xy);
        if (d < R) { s += (r.z * 2.0 - 1.0) * (0.5 + 0.5 * cos(PI * d / R)); } } } }
    return clamp(0.5 + s * mix(0.3, 1.0, k.z), 0.0, 1.0);
}

entries.caustics:
// caustics: overlapping sine sheets in absolute value, sharpened — the pool-floor look.
fn n_caustics(p: vec2f, t: f32, k: vec4f) -> f32 {
    var q = p * mix(1.0, 6.0, k.x); var s = 0.0; let tt = t * mix(0.0, 1.5, k.w);
    for (var i: i32 = 0; i < 4; i++) {
        q = rot2(0.9) * q + vec2f(sin(tt * 0.7 + f32(i)), cos(tt * 0.5 - f32(i))) * mix(0.0, 0.8, k.y);
        s += abs(sin(q.x * 2.0 + tt) + sin(q.y * 2.3 - tt * 0.8));
    }
    return pow(clamp(1.0 - s * 0.1, 0.0, 1.0), mix(1.0, 6.0, k.z));
}

entries.truchet:
// truchet: quarter-circle arcs in each cell, orientation from the hash — continuous curves from randomness.
fn n_truchet(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(0.5, 5.0, k.x) + t * 0.2 * k.w; let i = vec2i(floor(q)); var f = fract(q);
    if (h21(i, 193u) < 0.5) { f.x = 1.0 - f.x; }
    let d = min(abs(length(f) - 0.5), abs(length(f - 1.0) - 0.5));
    return fill(d - mix(0.02, 0.2, k.y), mix(0.005, 0.1, k.z));
}

entries.stars:
// stars: hashed points with sizes and a glow falloff.
fn n_stars(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(2.0, 10.0, k.x); let i = vec2i(floor(q)); let f = fract(q); var v = 0.0;
    for (var y: i32 = -1; y <= 1; y++) { for (var x: i32 = -1; x <= 1; x++) {
        let o = vec2i(x, y); let r = h3(vec3i(i + o, 0), 197u);
        if (r.z < mix(0.3, 0.9, k.y)) { continue; }
        let d = length(f - vec2f(o) - r.xy); let tw = 0.7 + 0.3 * sin(t * 3.0 * k.w + r.x * TAU);
        v += tw * pow(max(1.0 - d / mix(0.25, 0.9, k.z), 0.0), 2.5); } }
    return clamp(v * 1.6, 0.0, 1.0);
}

entries.flow_lines:
// flow lines: stripes aligned with the gradient of a noise field — hair, brushed metal, LIC-like.
fn n_flow_lines(p: vec2f, t: f32, k: vec4f) -> f32 {
    let q = p * mix(0.5, 3.0, k.x) + t * 0.05 * k.w; let e = 0.01;
    let v = fbm(q, 3, 2.0, 0.5, 199u);
    let g = vec2f(fbm(q + vec2f(e, 0.0), 3, 2.0, 0.5, 199u) - v, fbm(q + vec2f(0.0, e), 3, 2.0, 0.5, 199u) - v);
    let a = atan2(g.y, g.x);
    return 0.5 + 0.5 * sin(dot(p, vec2f(cos(a), sin(a))) * mix(20.0, 120.0, k.y) + v * mix(0.0, 40.0, k.z));
}

noise.adapter:
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let p = select(domain(fp.xy), textureSampleLevel(in0, smp, fp.xy / u.size, 0.0).xy, b.has0 > 0.5);
    let v = n___NAME__(p, u.time, u.k);
    return vec4f(v, v, v, 1.0);
}

field.uniform:
struct FieldU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    k: vec4f,
    speed: f32, fade: f32, frame: f32, seed: f32,
}
@group(0) @binding(0) var<uniform> u: FieldU;

field.core:
// ═══════════════════════════════════════════════════════════════════════════
//  FIELD TABLE  ·  2-D vector fields, one function per cell, drawn by particles.
//
//  Each cell is  fn v_<name>(p: vec2f, t: f32, k: vec4f) -> vec2f  — the
//  velocity at p (domain about ±1). A compute pass moves 4096 particles along
//  the field and deposits them into a trail texture that fades; a present pass
//  colors the trail by speed. The same field function is also evaluated per
//  pixel for the background: a faint LIC-like streak so the structure reads
//  even when the cell is still.
//
//  References: potential-flow elements (source, vortex, doublet, uniform stream)
//  from Anderson's aerodynamics; Taylor–Green vortices; Rankine vortex; curl
//  noise — Bridson, Hourihan & Nordenstam 2007; phase portraits (pendulum,
//  van der Pol, Duffing, Lotka–Volterra, Hopf, saddle/spiral/node, Lorenz
//  projection) — Strogatz, Nonlinear Dynamics and Chaos; gravitational and
//  Coulomb fields from point masses/charges; magnetic dipole field.
// ═══════════════════════════════════════════════════════════════════════════

const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;
const NP: u32 = 4096u;
const TS: i32 = 256;    // trail texture size

fn pcg(vin: vec3u) -> vec3u { var v = vin * 1664525u + 1013904223u; v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y; v ^= v >> vec3u(16u); v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y; return v; }
fn rnd3(i: u32, s: f32) -> vec3f { return vec3f(pcg(vec3u(i, u32(s * 1000.0) + 7u, 13u))) / 4294967295.0; }
fn rot2(a: f32) -> mat2x2f { let c = cos(a); let s = sin(a); return mat2x2f(c, s, -s, c); }
fn hash2(p: vec2i, seed: u32) -> vec2f { let q = pcg(vec3u(vec2u(p + vec2i(32768)), seed)); return vec2f(q.xy) / 4294967295.0; }
fn grad2(i: vec2i, seed: u32) -> vec2f { let a = hash2(i, seed).x * TAU; return vec2f(cos(a), sin(a)); }
fn fade(t: vec2f) -> vec2f { return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); }
fn pnoise(p: vec2f, seed: u32) -> f32 {
    let i = vec2i(floor(p)); let f = fract(p); let u = fade(f);
    let a = dot(grad2(i, seed), f); let b = dot(grad2(i + vec2i(1, 0), seed), f - vec2f(1.0, 0.0));
    let c = dot(grad2(i + vec2i(0, 1), seed), f - vec2f(0.0, 1.0)); let d = dot(grad2(i + vec2i(1, 1), seed), f - vec2f(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.414;
}
fn fbm(pin: vec2f, seed: u32) -> f32 { var p = pin; var a = 0.5; var s = 0.0; for (var i: i32 = 0; i < 4; i++) { s += a * pnoise(p, seed + u32(i)); a *= 0.5; p = rot2(0.5) * p * 2.0; } return s; }
fn grad_fbm(p: vec2f, t: f32, seed: u32) -> vec2f { let e = 0.01; let v = fbm(p + t, seed); return vec2f(fbm(p + vec2f(e, 0.0) + t, seed) - v, fbm(p + vec2f(0.0, e) + t, seed) - v) / e; }





















fn v_node(p: vec2f, t: f32, k: vec4f) -> vec2f { let l1 = mix(-1.0, 1.0, k.x); let l2 = mix(-1.0, 1.0, k.y); return vec2f(l1 * p.x, l2 * p.y) * 0.8; }






fn v_sine_flow(p: vec2f, t: f32, k: vec4f) -> vec2f { let a = mix(1.0, 4.0, k.x); return vec2f(sin(p.y * a * PI + t * 0.5), sin(p.x * a * PI - t * 0.4)) * 0.5; }
fn v_abc_slice(p: vec2f, t: f32, k: vec4f) -> vec2f { let A = 1.0; let B = mix(0.4, 1.2, k.x); let C = mix(0.4, 1.2, k.y); let z = t * 0.2; let q = p * PI; return vec2f(A * sin(z) + C * cos(q.y), B * sin(q.x) + A * cos(z)) * 0.3; }

// ═══════════════════════════════════════════════════════════ the runtime

entries.cylinder:
// cylinder: uniform stream plus a doublet — the textbook flow around a circle
fn v_cylinder(p: vec2f, t: f32, k: vec4f) -> vec2f {
    let R = mix(0.2, 0.5, k.x); let r2 = max(dot(p, p), R * R * 0.999); let r4 = r2 * r2;
    let U = 1.0; let circ = mix(-2.0, 2.0, k.y);
    var v = vec2f(U, 0.0) + U * R * R * vec2f((p.y * p.y - p.x * p.x), -2.0 * p.x * p.y) / r4 + circ * vec2f(-p.y, p.x) / r2 * 0.3;
    return select(v, vec2f(0.0), dot(p, p) < R * R);
}

entries.dipole_pair:
fn v_dipole_pair(p: vec2f, t: f32, k: vec4f) -> vec2f {
    let a = vec2f(-0.4, 0.0); let b = vec2f(0.4, 0.0); let pa = p - a; let pb = p - b; let s = mix(0.3, 1.5, k.x);
    return s * (vec2f(-pa.y, pa.x) / max(dot(pa, pa), 0.01) - vec2f(-pb.y, pb.x) / max(dot(pb, pb), 0.01));
}

entries.gravity:
// —— physics ———————————————————————————————————————————————————————————————
// gravity of three fixed masses, the field itself (not orbits): particles fall in and get flung by the softening
fn v_gravity(p: vec2f, t: f32, k: vec4f) -> vec2f {
    var g = vec2f(0.0); let eps = mix(0.02, 0.2, k.y);
    for (var i: i32 = 0; i < 3; i++) { let a = f32(i) * 2.094 + t * 0.15; let c = vec2f(cos(a), sin(a)) * mix(0.0, 0.6, k.x); let d = c - p; g += d / pow(dot(d, d) + eps * eps, 1.5) * 0.05; }
    return g;
}

entries.coulomb:
// electric field of two charges, sign from the knob
fn v_coulomb(p: vec2f, t: f32, k: vec4f) -> vec2f {
    let a = vec2f(-0.45, 0.0); let b = vec2f(0.45, 0.0); let qa = 1.0; let qb = select(-1.0, 1.0, k.y > 0.5);
    let pa = p - a; let pb = p - b; let eps = 0.03;
    return (qa * pa / pow(dot(pa, pa) + eps, 1.5) + qb * pb / pow(dot(pb, pb) + eps, 1.5)) * 0.08 * mix(0.5, 2.0, k.x);
}

entries.magnetic_dipole:
// magnetic dipole in the plane: B ∝ (3(m·r̂)r̂ − m)/r³
fn v_magnetic_dipole(p: vec2f, t: f32, k: vec4f) -> vec2f {
    let m = rot2(k.x * TAU + t * 0.1) * vec2f(0.0, 1.0); let r = length(p); let rh = p / max(r, 1e-3);
    return (3.0 * dot(m, rh) * rh - m) / max(r * r * r, 0.01) * 0.05;
}

field.adapter:
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let p = select(bench_p(fp.xy), textureSampleLevel(in0, smp, fp.xy / u.size, 0.0).xy, b.has0 > 0.5);
    let v = v___NAME__(p, u.time, u.k);
    return vec4f(p + u.speed * 0.5 * v, 0.0, 1.0);
}

sampling.uniform:
struct SampU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    count: f32, radius: f32, pad0: f32, pad1: f32,
    k: vec4f,
}
@group(0) @binding(0) var<uniform> u: SampU;

sampling.core:
// ═══════════════════════════════════════════════════════════════════════════
//  SAMPLING TABLE  ·  one point pattern per cell. Every pattern is a pure
//  function sample_<name>(i, n, k) -> vec2f giving the i-th of n points in the
//  unit square (or a sentinel off-square for a rejected slot). The cell draws
//  the first n points, colored by index, and hovering breathes the count so
//  the order of a sequence is visible.
//
//  References: stratified / N-rooks / multi-jittered — Shirley 1991, Chiu,
//  Shirley & Wang 1994; correlated multi-jittered — Kensler 2013 (permute);
//  Poisson disc by grid dominance — after Bridson 2007 / Wei 2008;
//  Halton 1960; Hammersley 1960; Sobol 1967 (first two dimensions);
//  Cranley–Patterson rotation 1976; R2 — Roberts 2018; Vogel 1979 (sunflower);
//  Fibonacci and rank-1 lattices — Niederreiter 1992; Bayer 1973 (ordered
//  dither); concentric disc map — Shirley & Chiu 1997; Box–Muller 1958;
//  spherical Fibonacci — González 2010; PCG hash — Jarzynski & Olano 2020.
// ═══════════════════════════════════════════════════════════════════════════


const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;
const PHI: f32 = 1.61803398874989;
const OFF: vec2f = vec2f(-10.0, -10.0);   // a rejected slot
const SEED: u32 = 7u;



// —— hashing and sequences ——————————————————————————————————————————————————
fn pcg(v: u32) -> u32 { let s = v * 747796405u + 2891336453u; let w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u; return (w >> 22u) ^ w; }
fn pcg2(p: vec2u) -> vec2u { var v = p * 1664525u + 1013904223u; v.x += v.y * 1664525u; v.y += v.x * 1664525u; v ^= v >> vec2u(16u); v.x += v.y * 1664525u; v.y += v.x * 1664525u; v ^= v >> vec2u(16u); return v; }
fn rnd(i: u32, s: u32) -> f32 { return f32(pcg(i * 3u + s * 977u)) / 4294967296.0; }
fn rnd2(i: u32, s: u32) -> vec2f { return vec2f(pcg2(vec2u(i, s))) / 4294967296.0; }
fn radinv2(i0: u32) -> f32 { return f32(reverseBits(i0)) * 2.3283064365386963e-10; }
fn radinv(i0: u32, base: u32) -> f32 { var i = i0; var f = 1.0; var r = 0.0; let inv = 1.0 / f32(base); loop { if (i == 0u) { break; } f *= inv; r += f * f32(i % base); i /= base; } return r; }
fn sobol2(i0: u32) -> f32 { var r = 0u; var v = 1u << 31u; var i = i0; loop { if (i == 0u) { break; } if ((i & 1u) != 0u) { r ^= v; } i >>= 1u; v ^= v >> 1u; } return f32(r) * 2.3283064365386963e-10; }
// Kensler's permute: a random permutation of 0..l-1 evaluated at i without building it
fn permute(i0: u32, l: u32, p: u32) -> u32 {
    var w = l - 1u; w |= w >> 1u; w |= w >> 2u; w |= w >> 4u; w |= w >> 8u; w |= w >> 16u;
    var i = i0;
    loop {
        i ^= p; i *= 0xe170893du; i ^= p >> 16u; i ^= (i & w) >> 4u; i ^= p >> 8u; i *= 0x0929eb3fu; i ^= p >> 23u; i ^= (i & w) >> 1u;
        i *= 1u | (p >> 27u); i *= 0x6935fa69u; i ^= (i & w) >> 11u; i *= 0x74dcb303u; i ^= (i & w) >> 2u; i *= 0x9e501cc3u; i ^= (i & w) >> 2u; i *= 0xc860a3dfu; i &= w; i ^= i >> 5u;
        if (i < l) { break; }
    }
    return (i + p) % l;
}
fn sq_side(n: u32) -> u32 { return max(u32(floor(sqrt(f32(n)))), 1u); }
fn bayer_inv(v: u32, kb: u32) -> vec2u {   // the cell whose Bayer rank is v, for a 2^kb square
    var x = 0u; var y = 0u;
    for (var b = 0u; b < kb; b++) { let xb = (v >> (2u * (kb - 1u - b))) & 1u; let s = (v >> (2u * (kb - 1u - b) + 1u)) & 1u; x |= xb << b; y |= (s ^ xb) << b; }
    return vec2u(x, y);
}


























// ═══ WARPS ═══ each takes a stratified point and maps it somewhere ═══════════
fn strat(i: u32, n: u32) -> vec2f { let m = sq_side(n); let j = i % (m * m); return (vec2f(f32(j % m), f32(j / m)) + rnd2(i, SEED)) / f32(m); }









// ═══ drawing ═════════════════════════════════════════════════════════════════
fn cell_uv(fp: vec2f) -> vec2f { let pos = fp / u.pixelScale; return (pos - 0.5 * u.size) / max(min(u.size.x, u.size.y), 1.0) * 1.12 + 0.5; }
fn shown() -> u32 { return u32(round(u.count * (0.7 + 0.3 * cos(u.time * 0.45)))); }
fn draw(fp: vec2f, d0: f32, idx: u32, ncount: u32) -> vec4f {
    let px = 1.12 / max(min(u.size.x, u.size.y), 1.0) / u.pixelScale;   // one device pixel in uv units
    let r = u.radius * px; let e = 1.0 * px;
    let uv = cell_uv(fp);
    let inside = step(0.0, uv.x) * step(0.0, uv.y) * step(uv.x, 1.0) * step(uv.y, 1.0);
    let bg = mix(u.ink.rgb, mix(u.ink.rgb, u.tone.rgb, 0.08), inside);
    let cov = 1.0 - smoothstep(r - e, r + e, d0);
    let t = f32(idx) / max(f32(ncount), 1.0);
    let col = mix(u.tone.rgb, u.cream.rgb, t * t);
    return vec4f(mix(bg, col, cov), 1.0);
}

entries.stratified:
fn sample_stratified(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let c = vec2f(f32(i % m), f32(i / m)); return (c + rnd2(i, SEED)) / f32(m);
}

entries.nrooks:
fn sample_nrooks(i: u32, n: u32, k: vec4f) -> vec2f {
    let j = permute(i, n, SEED * 0x51633e2du); let r = rnd2(i, SEED);
    return vec2f((f32(i) + r.x) / f32(n), (f32(j) + r.y) / f32(n));
}

entries.multijitter:
fn sample_multijitter(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); let nn = m * m; if (i >= nn) { return OFF; }
    let s = permute(i, nn, SEED * 0x51633e2du);
    let sx = permute(s % m, m, SEED * 0xa511e9b3u); let sy = permute(s / m, m, SEED * 0x63d83595u);
    let r = rnd2(s, SEED);
    return vec2f((f32(s % m) + (f32(sy) + r.x) / f32(m)) / f32(m), (f32(s / m) + (f32(sx) + r.y) / f32(m)) / f32(m));
}

entries.poisson_disc:
fn sample_poisson_disc(i: u32, n: u32, k: vec4f) -> vec2f {
    // one jittered candidate per grid cell; a candidate loses to any neighbour candidate closer than r with a lower rank
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let c = vec2i(i32(i % m), i32(i / m)); let p = (vec2f(c) + rnd2(i, SEED)) / f32(m);
    let rank = rnd(i, SEED + 3u); let r = mix(0.6, 1.15, k.z) / f32(m);
    for (var dy = -1; dy <= 1; dy++) { for (var dx = -1; dx <= 1; dx++) {
        if (dx == 0 && dy == 0) { continue; }
        let q = c + vec2i(dx, dy); if (q.x < 0 || q.y < 0 || q.x >= i32(m) || q.y >= i32(m)) { continue; }
        let j = u32(q.y) * m + u32(q.x); let pq = (vec2f(q) + rnd2(j, SEED)) / f32(m);
        if (distance(p, pq) < r && rnd(j, SEED + 3u) < rank) { return OFF; }
    } }
    return p;
}

entries.jittered_hex:
fn sample_jittered_hex(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let row = i / m; let col = i % m; let x = (f32(col) + 0.5 + 0.5 * f32(row % 2u)) / f32(m); let y = (f32(row) + 0.5) / f32(m);
    return vec2f(x, y) + (rnd2(i, SEED) - 0.5) * k.z * 0.9 / f32(m);
}

entries.gaussian_cloud:
fn sample_gaussian_cloud(i: u32, n: u32, k: vec4f) -> vec2f {
    let r = rnd2(i, SEED); let rad = sqrt(-2.0 * log(max(r.x, 1e-6))); let sg = mix(0.08, 0.25, k.z);
    return vec2f(0.5) + sg * rad * vec2f(cos(TAU * r.y), sin(TAU * r.y));
}

entries.golden_spiral:
fn sample_golden_spiral(i: u32, n: u32, k: vec4f) -> vec2f {
    let r = 0.5 * sqrt((f32(i) + 0.5) / f32(n)); let a = f32(i) * TAU / (PHI * PHI);
    return vec2f(0.5) + r * vec2f(cos(a), sin(a));
}

entries.rank1_lattice:
fn sample_rank1_lattice(i: u32, n: u32, k: vec4f) -> vec2f {
    let a = 1.0 + floor(k.z * 40.0); return fract(f32(i) / f32(n) * vec2f(1.0, a));
}

entries.bayer:
fn sample_bayer(i: u32, n: u32, k: vec4f) -> vec2f {
    // points in the order an ordered-dither matrix would turn them on: each new point lands as far as possible from the last
    let kb = max(u32(ceil(log2(sqrt(f32(n))))), 1u); let m = 1u << kb; if (i >= m * m) { return OFF; }
    return (vec2f(bayer_inv(i, kb)) + 0.5) / f32(m);
}

entries.hex:
fn sample_hex(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let row = i / m; let col = i % m; let x = (f32(col) + 0.5 + 0.5 * f32(row % 2u)) / f32(m); let y = (f32(row) + 0.5) / f32(m) * 0.8660254 + 0.067;
    return vec2f(x, y);
}

entries.brick:
fn sample_brick(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let row = i / m; let col = i % m; let shift = mix(0.0, 0.5, k.z) * f32(row % 2u);
    return vec2f(fract((f32(col) + 0.5 + shift) / f32(m)), (f32(row) + 0.5) / f32(m));
}

entries.quincunx:
fn sample_quincunx(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n / 2u); let nn = m * m; if (i >= 2u * nn) { return OFF; }
    let j = i % nn; let c = vec2f(f32(j % m), f32(j / m)) + 0.5; let off = select(vec2f(0.0), vec2f(0.5), i >= nn) - vec2f(0.25);
    return (c + off) / f32(m);
}

entries.rotated_grid:
fn sample_rotated_grid(i: u32, n: u32, k: vec4f) -> vec2f {
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let a = mix(0.0, PI * 0.5, k.z) * 0.59;   // default knob lands near atan(1/2), the classic RGSS angle
    let p = (vec2f(f32(i % m), f32(i / m)) + 0.5) / f32(m) - 0.5;
    let c = cos(a); let s = sin(a); return fract(vec2f(c * p.x - s * p.y, s * p.x + c * p.y) + 0.5);
}

entries.spiral:
fn sample_spiral(i: u32, n: u32, k: vec4f) -> vec2f {
    let t = (f32(i) + 0.5) / f32(n); let turns = mix(3.0, 14.0, k.z); let a = t * TAU * turns;
    return vec2f(0.5) + 0.48 * t * vec2f(cos(a), sin(a));
}

entries.disc_polar:
fn sample_disc_polar(i: u32, n: u32, k: vec4f) -> vec2f {   // the naive map: r = u — points crowd the centre
    let s = strat(i, n); let a = TAU * s.y; return vec2f(0.5) + 0.5 * s.x * vec2f(cos(a), sin(a));
}

entries.disc_sqrt:
fn sample_disc_sqrt(i: u32, n: u32, k: vec4f) -> vec2f {    // r = √u — uniform by area
    let s = strat(i, n); let a = TAU * s.y; return vec2f(0.5) + 0.5 * sqrt(s.x) * vec2f(cos(a), sin(a));
}

entries.disc_concentric:
fn sample_disc_concentric(i: u32, n: u32, k: vec4f) -> vec2f {   // Shirley–Chiu: the square's strata stay strata on the disc
    let s = strat(i, n) * 2.0 - 1.0;
    if (s.x == 0.0 && s.y == 0.0) { return vec2f(0.5); }
    var r: f32; var a: f32;
    if (abs(s.x) > abs(s.y)) { r = s.x; a = (PI / 4.0) * (s.y / s.x); } else { r = s.y; a = (PI / 2.0) - (PI / 4.0) * (s.x / s.y); }
    return vec2f(0.5) + 0.5 * r * vec2f(cos(a), sin(a));
}

entries.annulus:
fn sample_annulus(i: u32, n: u32, k: vec4f) -> vec2f {
    let s = strat(i, n); let r0 = mix(0.1, 0.45, k.z); let r = sqrt(mix(r0 * r0, 0.25, s.x)); let a = TAU * s.y;
    return vec2f(0.5) + r * vec2f(cos(a), sin(a));
}

entries.gaussian_bm:
fn sample_gaussian_bm(i: u32, n: u32, k: vec4f) -> vec2f {   // Box–Muller on stratified input: the strata survive as rings
    let s = strat(i, n); let rad = sqrt(-2.0 * log(max(1.0 - s.x, 1e-6))); let sg = mix(0.08, 0.25, k.z);
    return vec2f(0.5) + sg * rad * vec2f(cos(TAU * s.y), sin(TAU * s.y));
}

entries.tent:
fn sample_tent(i: u32, n: u32, k: vec4f) -> vec2f {   // jitter drawn from a tent filter: importance-sampled reconstruction
    let m = sq_side(n); if (i >= m * m) { return OFF; }
    let r = rnd2(i, SEED) * 2.0; let t = select(1.0 - sqrt(2.0 - r), sqrt(r) - 1.0, r < vec2f(1.0));
    return (vec2f(f32(i % m), f32(i / m)) + 0.5 + t * mix(0.3, 1.2, k.z)) / f32(m);
}

entries.sphere_fib:
fn sample_sphere_fib(i: u32, n: u32, k: vec4f) -> vec2f {   // spherical Fibonacci points seen from above: density piles up at the limb
    let z = 1.0 - 2.0 * (f32(i) + 0.5) / f32(n); let r = sqrt(max(1.0 - z * z, 0.0)); let a = f32(i) * TAU / PHI;
    return vec2f(0.5) + 0.49 * r * vec2f(cos(a), sin(a));
}

entries.triangle:
fn sample_triangle(i: u32, n: u32, k: vec4f) -> vec2f {   // uniform in a triangle via the √ warp of barycentrics
    let s = strat(i, n); let su = sqrt(s.x); let b0 = 1.0 - su; let b1 = s.y * su;
    let A = vec2f(0.08, 0.1); let B = vec2f(0.92, 0.1); let C = vec2f(0.5, 0.9);
    return A * b0 + B * b1 + C * (1.0 - b0 - b1);
}

sampling.adapter:
@fragment fn fs_main(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = select(cell_uv(fp.xy), textureSampleLevel(in0, smp, fp.xy / u.size, 0.0).xy * 0.5 + 0.5, b.has0 > 0.5);
    let n = u32(u.count); let m = shown(); var d0 = 1e9;
    for (var i = 0u; i < m; i++) { let p = sample___NAME__(i, n, u.k); d0 = min(d0, distance(uv, p)); }
    let px = 1.12 / max(min(u.size.x, u.size.y), 1.0) / u.pixelScale; let r = u.radius * px;
    let cov = 1.0 - smoothstep(r - px, r + px, d0);
    return vec4f(cov, cov, cov, 1.0);
}

color.uniform:
struct ColorU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    exposure: f32, contrast: f32, pad0: f32, pad1: f32,
    k: vec4f,
}
@group(0) @binding(0) var<uniform> u: ColorU;

color.core:
// ═══════════════════════════════════════════════════════════════════════════
//  COLOR & TONE TABLE  ·  one color function per cell, applied to a shared
//  scalar field v in 0..1 (the same field for every cell so the mappings can
//  be compared). The field is exposed as HDR for the tonemappers: hdr = v * exposure.
//
//  References: Quilez cosine palettes; viridis/magma/turbo polynomial fits
//  (Mikhailov's turbo fit, Garnier's viridis family fit); OKLab/OKLCH — Björn
//  Ottosson 2020; ACES fit — Narkowicz 2015; Uncharted 2 — Hable 2010; AgX —
//  Troy Sobotka / the Blender AgX sigmoid fit (Benjamin Wrensch); PBR Neutral
//  — Khronos 2023; Planckian locus fit — Kang et al. 2002; protanopia matrix —
//  Machado, Oliveira & Fernandes 2009; Bayer/IGN dithering as in the post table.
// ═══════════════════════════════════════════════════════════════════════════


const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;


fn cell_uv(fp: vec2f) -> vec2f { let pos = fp / u.pixelScale; return (pos - 0.5 * u.size) / max(min(u.size.x, u.size.y), 1.0) + 0.5; }
// the field, contrast-adjusted around 0.5
fn field(uv: vec2f) -> f32 { let v = textureSampleLevel(in0, smp, uv, 0.0).r; return clamp((v - 0.5) * u.contrast + 0.5, 0.0, 1.0); }
fn out(c: vec3f) -> vec4f { return vec4f(clamp(c, vec3f(0.0), vec3f(1.0)), 1.0); }
fn luma(c: vec3f) -> f32 { return dot(c, vec3f(0.2126, 0.7152, 0.0722)); }
fn srgb_to_linear(c: vec3f) -> vec3f { return select(c / 12.92, pow((c + 0.055) / 1.055, vec3f(2.4)), c > vec3f(0.04045)); }
fn linear_to_srgb(c: vec3f) -> vec3f { return select(c * 12.92, 1.055 * pow(c, vec3f(1.0 / 2.4)) - 0.055, c > vec3f(0.0031308)); }
fn hsv2rgb(h: f32, s: f32, v: f32) -> vec3f { let k = fract(vec3f(h, h + 2.0 / 3.0, h + 1.0 / 3.0)) * 6.0; let p = abs(k - 3.0) - 1.0; return v * mix(vec3f(1.0), clamp(p, vec3f(0.0), vec3f(1.0)), s); }
// OKLab (Ottosson): linear sRGB ↔ Lab
fn linear_to_oklab(c: vec3f) -> vec3f {
    let l = pow(0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b, 1.0 / 3.0);
    let m = pow(0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b, 1.0 / 3.0);
    let s = pow(0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b, 1.0 / 3.0);
    return vec3f(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s, 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
fn oklab_to_linear(lab: vec3f) -> vec3f {
    let l_ = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z; let m_ = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z; let s_ = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
    let l = l_ * l_ * l_; let m = m_ * m_ * m_; let s = s_ * s_ * s_;
    return vec3f(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
}
fn oklch(L: f32, C: f32, h: f32) -> vec3f { return clamp(linear_to_srgb(oklab_to_linear(vec3f(L, C * cos(h), C * sin(h)))), vec3f(0.0), vec3f(1.0)); }
fn rail(v: f32) -> vec3f { let lo = mix(u.ink.rgb, u.tone.rgb, smoothstep(0.0, 0.62, v)); return mix(lo, u.cream.rgb, smoothstep(0.62, 1.0, v)); }
fn hash21(p: vec2f) -> f32 { var q = fract(p * vec2f(123.34, 456.21)); q += dot(q, q + 45.32); return fract(q.x * q.y); }
fn ign(p: vec2f) -> f32 { return fract(52.9829189 * fract(dot(p, vec2f(0.06711056, 0.00583715)))); }















// —— tonemapping: the field as HDR light, exposure from the generator ————————
fn hdr(uv: vec2f) -> vec3f { let v = field(uv); return vec3f(v, pow(v, 1.4), pow(v, 2.2)) * u.exposure * 4.0 * mix(0.5, 2.0, u.k.x); }




fn hable(x: vec3f) -> vec3f { let A = 0.15; let B = 0.50; let C = 0.10; let D = 0.20; let E = 0.02; let F = 0.30; return ((x * (A * x + C * B) + D * E) / (x * (A * x + B) + D * F)) - E / F; }

// AgX: the sigmoid fit of Blender's AgX base (Wrensch), inset/outset matrices omitted for the 1-D case
fn agx_curve(x: vec3f) -> vec3f { let x2 = x * x; let x4 = x2 * x2; return 15.5 * x4 * x2 - 40.14 * x4 * x + 31.96 * x4 - 6.868 * x2 * x + 0.4298 * x2 + 0.1191 * x - 0.00232; }






@fragment fn fs_noise_dither(@builtin(position) fp: vec4f) -> @location(0) vec4f { let t = field(cell_uv(fp.xy)); let n = floor(mix(1.0, 5.0, u.k.x)); return out(rail(floor(t * n + hash21(floor(fp.xy / mix(1.0, 4.0, u.k.y)) + floor(u.time * 20.0))) / n)); }

entries.cosine:
// Quilez cosine palette: a + b·cos(2π(c·t + d))
@fragment fn fs_cosine(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy));
    let c = vec3f(1.0, 1.0, mix(0.5, 1.5, u.k.x)); let d = vec3f(0.0, mix(0.1, 0.5, u.k.y), mix(0.2, 0.8, u.k.z)) + u.time * 0.05;
    return out(0.5 + 0.5 * cos(TAU * (c * t + d)));
}

entries.turbo:
// turbo: Mikhailov's polynomial fit of Google's turbo colormap
@fragment fn fs_turbo(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy));
    let kR = vec4f(0.13572138, 4.61539260, -42.66032258, 132.13108234); let kG = vec4f(0.09140261, 2.19418839, 4.84296658, -14.18503333); let kB = vec4f(0.10667330, 12.64194608, -60.58204836, 110.36276771);
    let kR2 = vec2f(-152.94239396, 59.28637943); let kG2 = vec2f(4.27729857, 2.82956604); let kB2 = vec2f(-89.90310912, 27.34824973);
    let v4 = vec4f(1.0, t, t * t, t * t * t); let v2 = vec2f(t * t * t * t, t * t * t * t * t);
    return out(vec3f(dot(v4, kR) + dot(v2, kR2), dot(v4, kG) + dot(v2, kG2), dot(v4, kB) + dot(v2, kB2)));
}

entries.oklab_mix:
// OKLab interpolation between the tone and the cream (left: OKLab, right: sRGB)
@fragment fn fs_oklab_mix(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let t = field(uv);
    let a = srgb_to_linear(u.tone.rgb); let b = srgb_to_linear(u.cream.rgb);
    let lab = mix(linear_to_oklab(a), linear_to_oklab(b), t);
    let ok = linear_to_srgb(oklab_to_linear(lab)); let srgb = mix(u.tone.rgb, u.cream.rgb, t);
    return out(select(ok, srgb, uv.x > 0.5 + 0.02 * sin(u.time)));
}

entries.linear_vs_srgb:
// gradient interpolation in sRGB (top) vs linear light (bottom): the linear one has no dark seam
@fragment fn fs_linear_vs_srgb(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let t = field(uv); let a = vec3f(0.9, 0.2, 0.1); let b = vec3f(0.1, 0.3, 0.95);
    let s = mix(a, b, t); let l = linear_to_srgb(mix(srgb_to_linear(a), srgb_to_linear(b), t));
    return out(select(s, l, uv.y > 0.5));
}

entries.lab_lightness:
@fragment fn fs_lab_lightness(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy)); let lab = linear_to_oklab(srgb_to_linear(u.tone.rgb));
    return out(linear_to_srgb(oklab_to_linear(vec3f(mix(0.1, 0.98, t), lab.y * mix(0.3, 1.5, u.k.x), lab.z * mix(0.3, 1.5, u.k.x)))));
}

entries.agx:
@fragment fn fs_agx(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let c = hdr(cell_uv(fp.xy)); let minEv = -12.47393; let maxEv = 4.026069;
    let v = clamp((log2(max(c, vec3f(1e-5))) - minEv) / (maxEv - minEv), vec3f(0.0), vec3f(1.0));
    return out(agx_curve(v));
}

entries.pbr_neutral:
// Khronos PBR Neutral
@fragment fn fs_pbr_neutral(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    var c = hdr(cell_uv(fp.xy)); let startCompression = 0.8 - 0.04; let desaturation = 0.15;
    let x = min(c.r, min(c.g, c.b)); let offset = select(0.04, x - 6.25 * x * x, x < 0.08); c -= offset;
    let peak = max(c.r, max(c.g, c.b));
    if (peak >= startCompression) {
        let d = 1.0 - startCompression; let newPeak = 1.0 - d * d / (peak + d - startCompression); c *= newPeak / peak;
        let g = 1.0 - 1.0 / (desaturation * (peak - newPeak) + 1.0); c = mix(c, vec3f(newPeak), g);
    }
    return out(linear_to_srgb(c));
}

entries.bayer:
@fragment fn fs_bayer(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy)); let px = vec2i(floor(fp.xy / mix(1.0, 4.0, u.k.y)));
    let x = px.x & 3; let y = px.y & 3; let m = ((x ^ y) & 1) * 8 + (y & 1) * 4 + ((x ^ y) & 2) + ((y & 2) >> 1u);
    let thr = (f32(m) + 0.5) / 16.0; let n = floor(mix(1.0, 5.0, u.k.x));
    return out(rail(floor(t * n + thr) / n));
}

entries.palette_snap:
// snap to the nearest of eight fixed colors (a 3-bit palette)
@fragment fn fs_palette_snap(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy)); let c = hsv2rgb(t, 0.8, 0.9) + (ign(fp.xy) - 0.5) * mix(0.0, 0.5, u.k.y);
    var best = vec3f(0.0); var bd = 1e9;
    for (var i: i32 = 0; i < 8; i++) { let p = vec3f(f32(i & 1), f32((i >> 1u) & 1), f32((i >> 2u) & 1)) * mix(0.7, 1.0, u.k.x); let d = distance(p, c); if (d < bd) { bd = d; best = p; } }
    return out(best);
}

entries.hue_spin:
@fragment fn fs_hue_spin(@builtin(position) fp: vec4f) -> @location(0) vec4f { let t = field(cell_uv(fp.xy)); let c = rail(t); let a = u.time * 0.6 * mix(0.2, 1.0, u.k.x);
    let toYIQ = mat3x3f(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312); let toRGB = mat3x3f(1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703);
    var yiq = toYIQ * c; let h = atan2(yiq.z, yiq.y) + a; let ch = length(yiq.yz); yiq = vec3f(yiq.x, ch * cos(h), ch * sin(h)); return out(toRGB * yiq); }

entries.protanopia:
// protanopia simulation (Machado 2009, severity 1.0) of a hue sweep
@fragment fn fs_protanopia(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let c = hsv2rgb(field(uv), 0.9, 0.9);
    let M = mat3x3f(0.152286, 0.114503, -0.003882, 1.052583, 0.786281, -0.048116, -0.204868, 0.099216, 1.051998);
    return out(select(M * c, c, uv.y > 0.5));
}

entries.deuteranopia:
@fragment fn fs_deuteranopia(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let c = hsv2rgb(field(uv), 0.9, 0.9);
    let M = mat3x3f(0.367322, 0.280085, -0.011820, 0.860646, 0.672501, 0.042940, -0.227968, 0.047413, 0.968881);
    return out(select(M * c, c, uv.y > 0.5));
}

entries.split_tone:
@fragment fn fs_split_tone(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let t = field(cell_uv(fp.xy)); let sh = mix(vec3f(0.2, 0.3, 0.6), u.tone.rgb, u.k.x); let hi = mix(vec3f(1.0, 0.8, 0.5), u.cream.rgb, u.k.y);
    return out(mix(u.ink.rgb, mix(sh, hi, smoothstep(0.3, 0.8, t)), pow(t, 0.7)));
}

postfx.uniform:
struct PostU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    amt: f32, zoom: f32, pad0: f32, pad1: f32,
    k: vec4f,
}
@group(0) @binding(0) var<uniform> u: PostU;

postfx.core:
// ═══════════════════════════════════════════════════════════════════════════
//  POST-PROCESS TABLE  ·  image operators, one WGSL fragment function per cell.
//  Every cell reads the shared source texture through `src(uv)` and returns a
//  color. uv is 0..1 over the cell (aspect-corrected, zoomable), t the hover
//  clock, k the four knobs (0..1), amt the global strength.
//
//  References: Gaussian/bokeh/Kuwahara/DoG/unsharp — standard image-processing
//  formulations (Gonzalez & Woods); halftone/dither — Bayer ordered dithering,
//  interleaved gradient noise (Jimenez 2014); CRT — Lottes' "CRT shader" idea
//  (scanline + shadow mask + curvature); bloom — Jimenez 2014 bright-pass +
//  wide blur; barrel distortion — Brown–Conrady radial model; hue rotation in
//  YIQ (Ken Perlin's hue-shift matrix); OKLab — Björn Ottosson.
// ═══════════════════════════════════════════════════════════════════════════


const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;


fn cell_uv(fp: vec2f) -> vec2f {
    let pos = fp / u.pixelScale;
    let c = (pos - 0.5 * u.size) / max(min(u.size.x, u.size.y), 1.0);
    return c / u.zoom + 0.5;
}
fn src(uv: vec2f) -> vec3f { return textureSampleLevel(in0, smp, uv, 0.0).rgb; }
fn luma(c: vec3f) -> f32 { return dot(c, vec3f(0.2126, 0.7152, 0.0722)); }
fn texel() -> f32 { return 1.0 / 512.0; }
fn hash21(p: vec2f) -> f32 { var q = fract(p * vec2f(123.34, 456.21)); q += dot(q, q + 45.32); return fract(q.x * q.y); }
fn ign(p: vec2f) -> f32 { return fract(52.9829189 * fract(dot(p, vec2f(0.06711056, 0.00583715)))); }
fn rot2(a: f32) -> mat2x2f { let c = cos(a); let s = sin(a); return mat2x2f(c, s, -s, c); }
fn ramp(v: f32) -> vec3f { let lo = mix(u.ink.rgb, u.tone.rgb, smoothstep(0.0, 0.62, v)); return mix(lo, u.cream.rgb, smoothstep(0.62, 1.0, v)); }
fn out(c: vec3f) -> vec4f { return vec4f(clamp(c, vec3f(0.0), vec3f(1.0)), 1.0); }
// blend the operator result with the source by the global amount
fn done(uv: vec2f, c: vec3f) -> vec4f { return out(mix(src(uv), c, u.amt)); }

// —— blur / focus ————————————————————————————————————————————————————————
fn gauss9(uv: vec2f, dir: vec2f) -> vec3f {
    var w = array<f32, 5>(0.2270270270, 0.1945945946, 0.1216216216, 0.0540540541, 0.0162162162);
    var c = src(uv) * w[0];
    for (var i: i32 = 1; i < 5; i++) { c += (src(uv + dir * f32(i)) + src(uv - dir * f32(i))) * w[i]; }
    return c;
}
fn gauss2d(uv: vec2f, r: f32) -> vec3f {
    // 5x5 separable Gaussian sampled bilinearly, r in texels
    var c = vec3f(0.0); var nrm = 0.0;
    for (var y: i32 = -2; y <= 2; y++) { for (var x: i32 = -2; x <= 2; x++) {
        let o = vec2f(f32(x), f32(y)); let w = exp(-dot(o, o) * 0.35);
        c += src(uv + o * r * texel()) * w; nrm += w; } }
    return c / nrm;
}





















// —— edges / structure —————————————————————————————————————————————————————
fn sobel(uv: vec2f, s: f32) -> vec2f {
    let e = texel() * s;
    let tl = luma(src(uv + vec2f(-e, -e))); let tc = luma(src(uv + vec2f(0.0, -e))); let tr = luma(src(uv + vec2f(e, -e)));
    let ml = luma(src(uv + vec2f(-e, 0.0)));                                        let mr = luma(src(uv + vec2f(e, 0.0)));
    let bl = luma(src(uv + vec2f(-e, e)));  let bc = luma(src(uv + vec2f(0.0, e)));  let br = luma(src(uv + vec2f(e, e)));
    return vec2f((tr + 2.0 * mr + br) - (tl + 2.0 * ml + bl), (bl + 2.0 * bc + br) - (tl + 2.0 * tc + tr));
}


@fragment fn fs_sharpen(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let e = texel(); let c = src(uv);
    let n = src(uv + vec2f(0.0, -e)) + src(uv + vec2f(0.0, e)) + src(uv + vec2f(-e, 0.0)) + src(uv + vec2f(e, 0.0));
    return done(uv, c + (c * 4.0 - n) * mix(0.0, 2.0, u.k.x));
}

entries.gaussian:
@fragment fn fs_gaussian(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let r = mix(0.5, 8.0, u.k.x) * (1.0 + 0.15 * sin(u.time * 1.3));
    return done(uv, gauss2d(uv, r));
}

entries.bokeh:
// bokeh: golden-angle spiral of taps on a disc, bright taps weighted up (the "cat's eye" look)
@fragment fn fs_bokeh(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let R = mix(2.0, 24.0, u.k.x) * texel(); let n = 48;
    var c = vec3f(0.0); var nrm = 0.0;
    for (var i: i32 = 0; i < 48; i++) {
        let r = sqrt((f32(i) + 0.5) / f32(n)); let a = f32(i) * 2.39996323;
        let s = src(uv + vec2f(cos(a), sin(a)) * r * R);
        let w = 1.0 + mix(0.0, 8.0, u.k.y) * pow(luma(s), 4.0);
        c += s * w; nrm += w; }
    return done(uv, c / nrm);
}

entries.radial_blur:
@fragment fn fs_radial_blur(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let d = (uv - 0.5) * mix(0.0, 0.25, u.k.x); var c = vec3f(0.0);
    for (var i: i32 = 0; i < 16; i++) { c += src(uv - d * (f32(i) / 16.0)); }
    return done(uv, c / 16.0);
}

entries.motion_blur:
@fragment fn fs_motion_blur(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let a = u.k.y * PI + 0.2 * sin(u.time); let d = vec2f(cos(a), sin(a)) * mix(0.0, 0.08, u.k.x); var c = vec3f(0.0);
    for (var i: i32 = 0; i < 16; i++) { c += src(uv + d * ((f32(i) / 15.0) - 0.5)); }
    return done(uv, c / 16.0);
}

entries.tilt_shift:
@fragment fn fs_tilt_shift(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let focus = mix(0.2, 0.8, u.k.y) + 0.05 * sin(u.time * 0.7);
    let r = smoothstep(0.0, mix(0.1, 0.4, u.k.z), abs(uv.y - focus)) * mix(1.0, 8.0, u.k.x);
    return done(uv, gauss2d(uv, r));
}

entries.unsharp:
@fragment fn fs_unsharp(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let b = gauss2d(uv, mix(1.0, 4.0, u.k.y)); let s = src(uv);
    return done(uv, s + (s - b) * mix(0.0, 4.0, u.k.x));
}

entries.curves:
// —— color ————————————————————————————————————————————————————————————————
@fragment fn fs_curves(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); var c = src(uv);
    let contrast = mix(0.5, 2.5, u.k.x); let gamma = mix(0.4, 2.5, u.k.y); let lift = mix(-0.2, 0.2, u.k.z);
    c = (c - 0.5) * contrast + 0.5 + lift; c = pow(clamp(c, vec3f(0.0), vec3f(1.0)), vec3f(1.0 / gamma));
    return done(uv, c);
}

entries.saturation:
@fragment fn fs_saturation(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let c = src(uv); let l = luma(c);
    let sat = mix(0.0, 3.0, u.k.x); let vib = mix(0.0, 2.0, u.k.y) * (1.0 - max(max(c.r, c.g), c.b) + min(min(c.r, c.g), c.b));
    return done(uv, mix(vec3f(l), c, sat + vib));
}

entries.hue_rotate:
// hue rotation in YIQ (Perlin's matrix), animated on hover
@fragment fn fs_hue_rotate(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let c = src(uv); let a = u.k.x * TAU + u.time * 0.6 * u.k.y;
    let toYIQ = mat3x3f(0.299, 0.596, 0.211, 0.587, -0.274, -0.523, 0.114, -0.322, 0.312);
    let toRGB = mat3x3f(1.0, 1.0, 1.0, 0.956, -0.272, -1.106, 0.621, -0.647, 1.703);
    var yiq = toYIQ * c; let h = atan2(yiq.z, yiq.y) + a; let ch = length(yiq.yz);
    yiq = vec3f(yiq.x, ch * cos(h), ch * sin(h));
    return done(uv, toRGB * yiq);
}

entries.gradient_map:
@fragment fn fs_gradient_map(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let l = pow(luma(src(uv)), mix(0.5, 2.0, u.k.x));
    return done(uv, ramp(l));
}

entries.posterize:
@fragment fn fs_posterize(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let n = floor(mix(2.0, 12.0, u.k.x));
    return done(uv, floor(src(uv) * n + 0.5) / n);
}

entries.duotone:
@fragment fn fs_duotone(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let l = luma(src(uv));
    let shadow = mix(u.ink.rgb, vec3f(0.35, 0.10, 0.25), u.k.x); let hi = mix(u.cream.rgb, vec3f(1.0, 0.85, 0.55), u.k.y);
    return done(uv, mix(shadow, hi, pow(l, mix(0.5, 2.0, u.k.z))));
}

entries.grain:
// —— texture / print ————————————————————————————————————————————————————————
@fragment fn fs_grain(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let g = hash21(floor(fp.xy / mix(1.0, 4.0, u.k.y)) + floor(u.time * 24.0) * 0.37) - 0.5;
    let c = src(uv); let l = luma(c);
    return done(uv, c + g * mix(0.0, 0.6, u.k.x) * (1.0 - l * u.k.z));
}

entries.halftone:
// halftone: a rotated dot screen, dot radius from luminance
@fragment fn fs_halftone(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let cells = mix(20.0, 120.0, u.k.x); let ang = u.k.y * PI * 0.5 + 0.3;
    let q = rot2(ang) * (uv - 0.5) * cells; let cellc = floor(q) + 0.5; let center = rot2(-ang) * (cellc / cells) + 0.5;
    let l = luma(src(center)); let r = sqrt(1.0 - l) * 0.75;
    let d = length(q - cellc); let ink = 1.0 - smoothstep(r - 0.08, r + 0.08, d);
    return done(uv, mix(u.cream.rgb, u.ink.rgb, ink));
}

entries.hatching:
@fragment fn fs_hatching(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let f = mix(60.0, 220.0, u.k.x); let l = luma(src(uv)); var ink = 0.0;
    let q = uv * f;
    if (l < 0.75) { ink = max(ink, step(0.5, fract(q.x + q.y))); }
    if (l < 0.5) { ink = max(ink, step(0.5, fract(q.x - q.y))); }
    if (l < 0.3) { ink = max(ink, step(0.5, fract(q.y * 1.4))); }
    if (l < 0.12) { ink = 1.0; }
    return done(uv, mix(u.cream.rgb, u.ink.rgb, ink * mix(0.6, 1.0, u.k.y)));
}

entries.pixelate:
@fragment fn fs_pixelate(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let n = mix(8.0, 96.0, u.k.x) * (1.0 + 0.1 * sin(u.time));
    let q = (floor(uv * n) + 0.5) / n; var c = src(q);
    if (u.k.y > 0.5) { let lv = floor(mix(2.0, 8.0, u.k.z)); c = floor(c * lv + 0.5) / lv; }
    return done(uv, c);
}

entries.kuwahara:
// Kuwahara: the mean of the lowest-variance quadrant — the oil-paint filter
@fragment fn fs_kuwahara(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let r = mix(1.0, 6.0, u.k.x) * texel(); var best = vec3f(0.0); var bestVar = 1e9;
    for (var q: i32 = 0; q < 4; q++) {
        let sgn = vec2f(select(-1.0, 1.0, (q & 1) == 1), select(-1.0, 1.0, (q & 2) == 2));
        var m = vec3f(0.0); var m2 = vec3f(0.0);
        for (var y: i32 = 0; y < 4; y++) { for (var x: i32 = 0; x < 4; x++) {
            let c = src(uv + sgn * vec2f(f32(x), f32(y)) * r * 0.75); m += c; m2 += c * c; } }
        m /= 16.0; m2 = m2 / 16.0 - m * m; let v = m2.r + m2.g + m2.b;
        if (v < bestVar) { bestVar = v; best = m; }
    }
    return done(uv, best);
}

entries.dither:
@fragment fn fs_dither(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let px = floor(fp.xy / mix(1.0, 4.0, u.k.y));
    let n = ign(px) - 0.5; let l = luma(src(uv)) + n * mix(0.2, 1.0, u.k.x);
    let lv = floor(mix(1.0, 6.0, u.k.z)); let q = floor(l * lv + 0.5) / lv;
    return done(uv, mix(u.ink.rgb, u.cream.rgb, q));
}

entries.sobel:
@fragment fn fs_sobel(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let g = sobel(uv, mix(0.5, 3.0, u.k.y)); let m = clamp(length(g) * mix(0.5, 4.0, u.k.x), 0.0, 1.0);
    return done(uv, ramp(m));
}

entries.emboss:
@fragment fn fs_emboss(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let a = u.k.y * TAU + u.time * 0.5; let e = texel() * mix(1.0, 4.0, u.k.z) * vec2f(cos(a), sin(a));
    let d = luma(src(uv + e)) - luma(src(uv - e));
    return done(uv, vec3f(0.5 + d * mix(1.0, 6.0, u.k.x)));
}

entries.dog_sketch:
// difference of Gaussians, thresholded — the pencil sketch
@fragment fn fs_dog_sketch(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let a = luma(gauss2d(uv, 1.0)); let b = luma(gauss2d(uv, mix(2.0, 5.0, u.k.x)));
    let d = (a - b) * mix(4.0, 20.0, u.k.y); let ink = smoothstep(0.0, 0.3, -d);
    return done(uv, mix(u.cream.rgb, u.ink.rgb, ink));
}

entries.edge_glow:
@fragment fn fs_edge_glow(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let g = length(sobel(uv, 1.5)); let c = src(uv);
    return done(uv, c * 0.5 + u.tone.rgb * g * mix(0.5, 3.0, u.k.x) + u.cream.rgb * pow(g, 3.0));
}

entries.bloom:
// —— lens / display ————————————————————————————————————————————————————————
@fragment fn fs_bloom(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let thr = mix(0.3, 0.9, u.k.y); var b = vec3f(0.0); var nrm = 0.0;
    for (var i: i32 = 0; i < 32; i++) {
        let r = sqrt((f32(i) + 0.5) / 32.0); let a = f32(i) * 2.39996323;
        let s = src(uv + vec2f(cos(a), sin(a)) * r * mix(0.02, 0.12, u.k.z)); let w = 1.0 - r;
        b += max(s - thr, vec3f(0.0)) * w; nrm += w; }
    return done(uv, src(uv) + b / nrm * mix(0.0, 4.0, u.k.x));
}

entries.vignette:
@fragment fn fs_vignette(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let d = length((uv - 0.5) * vec2f(1.0, mix(0.6, 1.4, u.k.z)));
    let v = 1.0 - smoothstep(mix(0.2, 0.6, u.k.y), 0.9, d) * u.k.x;
    return done(uv, src(uv) * v);
}

entries.aberration:
@fragment fn fs_aberration(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let d = (uv - 0.5) * mix(0.0, 0.06, u.k.x) * (1.0 + 0.3 * sin(u.time * 2.0) * u.k.y);
    return done(uv, vec3f(src(uv + d).r, src(uv).g, src(uv - d).b));
}

entries.barrel:
// Brown–Conrady radial distortion
@fragment fn fs_barrel(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let c = uv - 0.5; let r2 = dot(c, c); let k1 = mix(-0.6, 0.8, u.k.x) + 0.2 * sin(u.time * 0.8) * u.k.y;
    let q = c * (1.0 + k1 * r2) + 0.5;
    let inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
    return done(uv, src(q) * inside);
}

entries.crt:
@fragment fn fs_crt(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    var uv = cell_uv(fp.xy); let c = uv - 0.5; uv = c * (1.0 + mix(0.0, 0.25, u.k.z) * dot(c, c)) + 0.5;
    let inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
    var col = src(uv) * inside;
    let lines = mix(120.0, 320.0, u.k.x); let scan = 0.75 + 0.25 * sin(uv.y * lines * PI * 2.0 + u.time * 6.0);
    let m = i32(fp.x) % 3; let mask = vec3f(select(0.6, 1.0, m == 0), select(0.6, 1.0, m == 1), select(0.6, 1.0, m == 2));
    col = col * scan * mix(vec3f(1.0), mask, u.k.y) * 1.25;
    return done(uv, col);
}

entries.glitch:
@fragment fn fs_glitch(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    var uv = cell_uv(fp.xy); let t = floor(u.time * 12.0);
    let row = floor(uv.y * mix(8.0, 40.0, u.k.y)); let h = hash21(vec2f(row, t));
    let on = step(1.0 - mix(0.05, 0.5, u.k.x), h);
    uv.x += on * (hash21(vec2f(t, row)) - 0.5) * 0.3;
    let block = step(0.97, hash21(floor(uv * 12.0) + t));
    var col = vec3f(src(uv + on * vec2f(0.01, 0.0)).r, src(uv).g, src(uv - on * vec2f(0.01, 0.0)).b);
    col = mix(col, u.tone.rgb, block * u.k.z);
    return done(uv, col);
}

entries.shimmer:
@fragment fn fs_shimmer(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); let q = uv * mix(3.0, 12.0, u.k.y);
    let d = vec2f(sin(q.y * 2.0 + u.time * 2.0) + sin(q.y * 3.7 - u.time * 1.3), cos(q.x * 2.3 + u.time * 1.7)) * mix(0.0, 0.03, u.k.x);
    return done(uv, src(uv + d));
}

entries.old_film:
@fragment fn fs_old_film(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let uv = cell_uv(fp.xy); var c = src(uv); let l = luma(c);
    c = mix(vec3f(l), c, 0.3) * vec3f(1.0, 0.92, 0.78);
    let frame = floor(u.time * 18.0);
    c += (hash21(fp.xy + frame) - 0.5) * mix(0.05, 0.4, u.k.x);
    let sx = hash21(vec2f(frame, 3.0)); let scratch = step(0.995, 1.0 - abs(uv.x - sx) * 60.0 * hash21(vec2f(frame, floor(uv.y * 8.0))));
    c = mix(c, vec3f(0.9), scratch * step(0.5, hash21(vec2f(frame, 7.0))) * u.k.y);
    c *= 0.85 + 0.15 * hash21(vec2f(frame, 1.0));
    c *= 1.0 - smoothstep(0.3, 0.85, length(uv - 0.5)) * 0.7;
    return done(uv, c);
}

lighting.uniform:
struct LightU {
    size: vec2f, time: f32, pixelScale: f32,
    ink: vec4f, tone: vec4f, cream: vec4f,
    exposure: f32, ambient: f32, lx: f32, ly: f32,   // key light direction (x, y); z follows
    k: vec4f,
}
@group(0) @binding(0) var<uniform> u: LightU;

lighting.core:
// ═══════════════════════════════════════════════════════════════════════════
//  LIGHTING TABLE  ·  one shading model per cell, on an analytic sphere lit by
//  a key light that orbits while hovered plus a hemisphere ambient. All math in
//  linear light; base color is the site tone, the light is the cream.
//
//  References: Lambert; Valve half-Lambert (Mitchell et al. 2007); wrap
//  lighting (Green, GPU Gems 2005); Oren–Nayar 1994 (qualitative model);
//  Burley 2012 (Disney diffuse, clearcoat, GTR, sheen, subsurface approx.);
//  Minnaert 1941; Lommel–Seeliger (lunar); Phong 1975; Blinn 1977; Beckmann
//  1963 / Cook–Torrance 1982; Trowbridge–Reitz 1975 / Walter et al. 2007 (GGX,
//  Smith G); Ward 1992; Ashikhmin–Shirley 2000; Kelemen–Szirmay-Kalos 2001;
//  Schlick 1994; Estevez & Kulla 2017 (Charlie sheen); Belcour & Barla 2017
//  (thin-film, simplified); Gooch et al. 1998; Lake et al. 2000 (cel shading);
//  Praun et al. 2001 (tonal art maps / hatching).
// ═══════════════════════════════════════════════════════════════════════════


const PI: f32 = 3.14159265358979;
const TAU: f32 = 6.28318530717959;


fn srgb_to_linear(c: vec3f) -> vec3f { return select(c / 12.92, pow((c + 0.055) / 1.055, vec3f(2.4)), c > vec3f(0.04045)); }
fn linear_to_srgb(c: vec3f) -> vec3f { return select(c * 12.92, 1.055 * pow(c, vec3f(1.0 / 2.4)) - 0.055, c > vec3f(0.0031308)); }
fn sq(x: f32) -> f32 { return x * x; }

// —— the sphere and its lights ————————————————————————————————————————————
struct Surf { n: vec3f, v: vec3f, l: vec3f, h: vec3f, t: vec3f, b: vec3f, ndl: f32, ndv: f32, ndh: f32, vdh: f32, ldh: f32, mask: f32, uv: vec2f }
fn setup(fp: vec2f) -> Surf {
    let pos = fp / u.pixelScale; let px = 1.0 / max(min(u.size.x, u.size.y), 1.0);
    let uv = (pos - 0.5 * u.size) * px * 2.0;   // -1..1 across the short side
    let r2 = dot(uv, uv); let R = 0.92;
    var s: Surf; s.uv = uv;
    s.mask = 1.0 - smoothstep(R * R - 3.0 * px, R * R + px, r2);
    let z = sqrt(max(R * R - r2, 0.0));
    s.n = normalize(vec3f(uv.x, -uv.y, z + 1e-4));
    s.v = vec3f(0.0, 0.0, 1.0);
    let lz = sqrt(max(1.0 - (u.lx * u.lx + u.ly * u.ly), 0.0));   // (lx, ly) is the unit light direction's xy
    s.l = normalize(vec3f(u.lx, u.ly, lz + 1e-3));
    s.h = normalize(s.l + s.v);
    // tangent frame for the anisotropic lobes: brushed around the y axis
    let up = vec3f(0.0, 1.0, 0.0);
    s.t = normalize(cross(up, s.n) + vec3f(1e-4, 0.0, 0.0)); s.b = cross(s.n, s.t);
    s.ndl = max(dot(s.n, s.l), 0.0); s.ndv = max(dot(s.n, s.v), 1e-4); s.ndh = max(dot(s.n, s.h), 0.0);
    s.vdh = max(dot(s.v, s.h), 0.0); s.ldh = max(dot(s.l, s.h), 0.0);
    return s;
}
fn albedo() -> vec3f { return srgb_to_linear(u.tone.rgb); }
fn light() -> vec3f { return srgb_to_linear(u.cream.rgb) * 2.2; }
// hemisphere ambient: sky is the tone, ground is the ink
fn ambient(n: vec3f) -> vec3f { return mix(srgb_to_linear(u.ink.rgb) * 0.6, srgb_to_linear(u.tone.rgb) * 0.7, 0.5 + 0.5 * n.y) * u.ambient; }
// composite radiance to the cell: sphere over ink, exposure, sRGB
fn out(s: Surf, c: vec3f) -> vec4f {
    let bg = srgb_to_linear(u.ink.rgb);
    let col = mix(bg, max(c, vec3f(0.0)) * u.exposure, s.mask);
    return vec4f(clamp(linear_to_srgb(col), vec3f(0.0), vec3f(1.0)), 1.0);
}
fn shade(s: Surf, diffuse: vec3f, spec: vec3f) -> vec4f { return out(s, (diffuse + spec) * light() * s.ndl + albedo() * ambient(s.n)); }
fn rough() -> f32 { return mix(0.06, 1.0, u.k.x); }
// the microfacet denominator, with n·v floored so the silhouette doesn't blow up where no G term tames it
fn denom(s: Surf) -> f32 { return 4.0 * max(s.ndv, 0.08) * max(s.ndl, 1e-3); }

// —— microfacet building blocks ————————————————————————————————————————————
fn f_schlick(f0: vec3f, c: f32) -> vec3f { let m = pow(1.0 - c, 5.0); return f0 + (1.0 - f0) * m; }
fn d_ggx(ndh: f32, a: f32) -> f32 { let a2 = a * a; let d = ndh * ndh * (a2 - 1.0) + 1.0; return a2 / (PI * d * d + 1e-6); }
fn d_beckmann(ndh: f32, a: f32) -> f32 { let c2 = max(ndh * ndh, 1e-4); let t2 = (1.0 - c2) / c2; return exp(-t2 / (a * a)) / (PI * a * a * c2 * c2); }
fn d_gtr(ndh: f32, a: f32, g: f32) -> f32 { let a2 = a * a; let d = ndh * ndh * (a2 - 1.0) + 1.0; return select((g - 1.0) * (a2 - 1.0) / (PI * (1.0 - pow(a2, 1.0 - g))) / pow(d, g), a2 / (PI * d * d), abs(g - 1.0) < 1e-3 || abs(a2 - 1.0) < 1e-4); }
fn g1_smith_ggx(ndx: f32, a: f32) -> f32 { let a2 = a * a; return 2.0 * ndx / (ndx + sqrt(a2 + (1.0 - a2) * ndx * ndx)); }
fn g_smith_ggx(ndl: f32, ndv: f32, a: f32) -> f32 { return g1_smith_ggx(ndl, a) * g1_smith_ggx(ndv, a); }
fn d_ggx_aniso(s: Surf, ax: f32, ay: f32) -> f32 {
    let hx = dot(s.h, s.t) / ax; let hy = dot(s.h, s.b) / ay; let d = hx * hx + hy * hy + s.ndh * s.ndh;
    return 1.0 / (PI * ax * ay * d * d + 1e-6);
}
fn d_charlie(ndh: f32, a: f32) -> f32 { let inv = 1.0 / max(a, 1e-3); let s2 = 1.0 - ndh * ndh; return (2.0 + inv) * pow(s2, inv * 0.5) / TAU; }



































@fragment fn fs_xray(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let e = pow(1.0 - s.ndv, mix(0.5, 3.0, u.k.x));
    let c = srgb_to_linear(u.tone.rgb) * e * 2.0 + srgb_to_linear(u.cream.rgb) * pow(e, 4.0);
    return out(s, c);
}

entries.half_lambert:
@fragment fn fs_half_lambert(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let hl = sq(0.5 * dot(s.n, s.l) + 0.5);
    return out(s, albedo() / PI * light() * hl + albedo() * ambient(s.n));
}

entries.wrap:
@fragment fn fs_wrap(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let w = mix(0.0, 1.0, u.k.x); let d = max((dot(s.n, s.l) + w) / (1.0 + w), 0.0);
    return out(s, albedo() / PI * light() * d + albedo() * ambient(s.n));
}

entries.oren_nayar:
@fragment fn fs_oren_nayar(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let sg = rough(); let s2 = sg * sg;
    let A = 1.0 - 0.5 * s2 / (s2 + 0.33); let B = 0.45 * s2 / (s2 + 0.09);
    let tl = acos(clamp(dot(s.n, s.l), -1.0, 1.0)); let tv = acos(clamp(s.ndv, -1.0, 1.0));
    let pl = normalize(s.l - s.n * dot(s.n, s.l) + vec3f(1e-5)); let pv = normalize(s.v - s.n * s.ndv + vec3f(1e-5));
    let cosd = max(dot(pl, pv), 0.0);
    let f = A + B * cosd * sin(max(tl, tv)) * tan(min(tl, tv));
    return shade(s, albedo() / PI * f, vec3f(0.0));
}

entries.burley:
@fragment fn fs_burley(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let r = rough();
    let fd90 = 0.5 + 2.0 * r * s.ldh * s.ldh;
    let fl = 1.0 + (fd90 - 1.0) * pow(1.0 - s.ndl, 5.0); let fv = 1.0 + (fd90 - 1.0) * pow(1.0 - s.ndv, 5.0);
    return shade(s, albedo() / PI * fl * fv, vec3f(0.0));
}

entries.minnaert:
@fragment fn fs_minnaert(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let kk = mix(0.5, 2.0, u.k.x);
    let f = pow(max(s.ndl * s.ndv, 1e-4), kk - 1.0);
    return shade(s, albedo() / PI * f, vec3f(0.0));
}

entries.lommel_seeliger:
@fragment fn fs_lommel_seeliger(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let f = 1.0 / (s.ndl + s.ndv + 1e-3);
    return shade(s, albedo() / PI * f * 0.5, vec3f(0.0));
}

entries.hemisphere:
@fragment fn fs_hemisphere(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy);   // ambient only: the sky/ground hemisphere, the key light off
    return out(s, albedo() * ambient(s.n) * mix(2.0, 6.0, u.k.x));
}

entries.phong:
// ═══ SPECULAR ════════════════════════════════════════════════════════════════
@fragment fn fs_phong(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let r = reflect(-s.l, s.n); let n = mix(4.0, 200.0, u.k.x * u.k.x);
    let sp = pow(max(dot(r, s.v), 0.0), n) * (n + 2.0) / TAU;
    return shade(s, albedo() / PI, vec3f(sp) * mix(0.1, 1.0, u.k.y));
}

entries.blinn_phong:
@fragment fn fs_blinn_phong(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let n = mix(4.0, 400.0, u.k.x * u.k.x);
    let sp = pow(s.ndh, n) * (n + 8.0) / (8.0 * PI);
    return shade(s, albedo() / PI, vec3f(sp) * mix(0.1, 1.0, u.k.y));
}

entries.gaussian:
@fragment fn fs_gaussian(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let m = rough() * 0.8; let ang = acos(clamp(s.ndh, 0.0, 1.0));
    let sp = exp(-sq(ang / m)) / (PI * m * m);
    return shade(s, albedo() / PI, vec3f(sp) * 0.5);
}

entries.beckmann:
@fragment fn fs_beckmann(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough();
    let sp = d_beckmann(s.ndh, a) * f_schlick(vec3f(0.04), s.vdh) / denom(s);
    return shade(s, albedo() / PI, sp);
}

entries.ggx:
@fragment fn fs_ggx(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough();
    let sp = d_ggx(s.ndh, a) * f_schlick(vec3f(0.04), s.vdh) / denom(s);
    return shade(s, albedo() / PI, sp);
}

entries.gtr:
@fragment fn fs_gtr(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough(); let g = mix(0.5, 3.0, u.k.y);   // γ: 1 = Berry, 2 = GGX
    let sp = d_gtr(s.ndh, a, g) * f_schlick(vec3f(0.04), s.vdh) / denom(s);
    return shade(s, albedo() / PI, sp);
}

entries.cook_torrance:
@fragment fn fs_cook_torrance(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough(); let metal = u.k.y;
    let f0 = mix(vec3f(0.04), albedo(), metal); let F = f_schlick(f0, s.vdh);
    let sp = d_ggx(s.ndh, a) * g_smith_ggx(s.ndl, s.ndv, a) * F / denom(s);
    let kd = (1.0 - F) * (1.0 - metal);
    return shade(s, kd * albedo() / PI, sp);
}

entries.kelemen:
@fragment fn fs_kelemen(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough();
    // Kelemen–Szirmay-Kalos: G/(4 n·l n·v) ≈ 1/(v·h)²
    let sp = d_ggx(s.ndh, a) * f_schlick(vec3f(0.04), s.vdh) / (4.0 * max(s.vdh * s.vdh, 1e-3));
    return shade(s, albedo() / PI, sp);
}

entries.ward:
@fragment fn fs_ward(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let ax = mix(0.05, 0.6, u.k.x); let ay = mix(0.05, 0.6, u.k.y);
    let hx = dot(s.h, s.t) / ax; let hy = dot(s.h, s.b) / ay;
    let e = exp(-(hx * hx + hy * hy) / max(s.ndh * s.ndh, 1e-4));
    let sp = e / (4.0 * PI * ax * ay * sqrt(max(s.ndl * s.ndv, 1e-4)));
    return shade(s, albedo() / PI, vec3f(sp) * 0.3);
}

entries.ashikhmin_shirley:
@fragment fn fs_ashikhmin_shirley(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let nu = mix(10.0, 1000.0, u.k.x * u.k.x); let nv = mix(10.0, 1000.0, u.k.y * u.k.y);
    let hu = dot(s.h, s.t); let hv = dot(s.h, s.b); let denom = max(1.0 - s.ndh * s.ndh, 1e-4);
    let ex = (nu * hu * hu + nv * hv * hv) / denom;
    let sp = sqrt((nu + 1.0) * (nv + 1.0)) / (8.0 * PI) * pow(s.ndh, ex) / (s.vdh * max(max(s.ndl, s.ndv), 1e-3));
    let rs = 0.1; let F = rs + (1.0 - rs) * pow(1.0 - s.vdh, 5.0);
    let dif = 28.0 * albedo() / (23.0 * PI) * (1.0 - rs) * (1.0 - pow(1.0 - s.ndl * 0.5, 5.0)) * (1.0 - pow(1.0 - s.ndv * 0.5, 5.0));
    return shade(s, dif, vec3f(sp * F));
}

entries.ggx_aniso:
@fragment fn fs_ggx_aniso(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough(); let an = mix(-0.9, 0.9, u.k.y);
    let ax = max(a * (1.0 + an), 1e-3); let ay = max(a * (1.0 - an), 1e-3);
    let sp = d_ggx_aniso(s, ax, ay) * g_smith_ggx(s.ndl, s.ndv, a) * f_schlick(vec3f(0.04), s.vdh) / denom(s);
    return shade(s, albedo() / PI, sp);
}

entries.fresnel:
// ═══ FRESNEL & LAYERS ════════════════════════════════════════════════════════
@fragment fn fs_fresnel(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let ior = mix(1.0, 2.5, u.k.x); let f0 = sq((ior - 1.0) / (ior + 1.0));
    let F = f_schlick(vec3f(f0), s.ndv);   // the view-angle Fresnel term alone, over the ink
    return out(s, F * light() * 0.5 + albedo() * ambient(s.n) * 0.3);
}

entries.metal:
@fragment fn fs_metal(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough(); let metal = smoothstep(-0.02, 0.02, s.uv.x);   // left dielectric, right metal
    let f0 = mix(vec3f(0.04), albedo(), metal); let F = f_schlick(f0, s.vdh);
    let sp = d_ggx(s.ndh, a) * g_smith_ggx(s.ndl, s.ndv, a) * F / denom(s);
    return shade(s, (1.0 - F) * (1.0 - metal) * albedo() / PI, sp + f0 * ambient(reflect(-s.v, s.n)) * 0.6);
}

entries.clearcoat:
@fragment fn fs_clearcoat(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = rough() * rough(); let cc = u.k.y; let ca = mix(0.001, 0.1, u.k.z);
    let base = d_ggx(s.ndh, a) * g_smith_ggx(s.ndl, s.ndv, a) * f_schlick(vec3f(0.04), s.vdh) / denom(s);
    let coat = d_gtr(s.ndh, sqrt(ca), 1.0) * 0.25 * f_schlick(vec3f(0.04), s.vdh).x * g_smith_ggx(s.ndl, s.ndv, 0.25) / denom(s);
    return shade(s, albedo() / PI, base + vec3f(coat) * cc);
}

entries.sheen:
@fragment fn fs_sheen(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let a = mix(0.1, 1.0, u.k.x);
    let sh = d_charlie(s.ndh, a) / (4.0 * (s.ndl + s.ndv - s.ndl * s.ndv) + 1e-3);   // Neubelt–Pettineo visibility
    return shade(s, albedo() / PI, srgb_to_linear(u.cream.rgb) * sh * u.k.y * 2.0);
}

entries.subsurface:
@fragment fn fs_subsurface(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let r = rough();
    // Disney's subsurface approximation (Hanrahan–Krueger inspired), lerped against Burley diffuse
    let fss90 = s.ldh * s.ldh * r; let fl = pow(1.0 - s.ndl, 5.0); let fv = pow(1.0 - s.ndv, 5.0);
    let fss = mix(1.0, fss90, fl) * mix(1.0, fss90, fv);
    let ss = 1.25 * (fss * (1.0 / (s.ndl + s.ndv + 1e-3) - 0.5) + 0.5);
    let fd90 = 0.5 + 2.0 * r * s.ldh * s.ldh; let fd = mix(1.0, fd90, fl) * mix(1.0, fd90, fv);
    // wrapped transmission through the thin side so the terminator glows
    let trans = pow(max(dot(-s.v, s.l), 0.0), 3.0) * 0.4 * u.k.y;
    let d = albedo() / PI * mix(fd, ss, u.k.y);
    return out(s, (d * s.ndl + albedo() * trans) * light() + albedo() * ambient(s.n));
}

entries.thin_film:
@fragment fn fs_thin_film(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let thick = mix(100.0, 700.0, u.k.x); let ior = mix(1.2, 2.0, u.k.y);
    // simplified thin-film interference: per-wavelength cosine of the optical path difference
    let ct = sqrt(max(1.0 - (1.0 - s.ndv * s.ndv) / (ior * ior), 0.0)); let opd = 2.0 * ior * thick * ct;
    let lam = vec3f(650.0, 550.0, 450.0); let irid = 0.5 + 0.5 * cos(TAU * opd / lam + PI);
    let a = 0.05; let sp = d_ggx(s.ndh, a) * irid * 0.06 / denom(s);
    return shade(s, albedo() / PI * 0.4, sp + irid * f_schlick(vec3f(0.04), s.ndv) * 0.6);
}

entries.toon:
// ═══ STYLIZED ════════════════════════════════════════════════════════════════
@fragment fn fs_toon(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let bands = floor(mix(2.0, 6.0, u.k.x));
    let d = floor(s.ndl * bands + 0.5) / bands; let sp = step(0.9 + 0.09 * u.k.y, s.ndh);
    let rim = step(1.0 - mix(0.1, 0.4, u.k.z), 1.0 - s.ndv);
    let c = albedo() * mix(0.25, 1.0, d) + srgb_to_linear(u.cream.rgb) * (sp + rim * 0.5);
    return out(s, c);
}

entries.gooch:
@fragment fn fs_gooch(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let t = 0.5 + 0.5 * dot(s.n, s.l);
    let cool = vec3f(0.0, 0.0, 0.55) + mix(0.1, 0.5, u.k.x) * albedo(); let warm = vec3f(0.3, 0.3, 0.0) + mix(0.1, 0.5, u.k.y) * albedo();
    let r = reflect(-s.l, s.n); let sp = pow(max(dot(r, s.v), 0.0), 32.0);
    return out(s, mix(cool, warm, t) + vec3f(sp) * 0.6);
}

entries.rim:
@fragment fn fs_rim(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let p = mix(0.8, 4.0, u.k.x);
    let rim = pow(1.0 - s.ndv, p) * mix(0.5, 3.0, u.k.y);
    return out(s, albedo() * 0.06 + srgb_to_linear(u.tone.rgb) * rim + albedo() / PI * light() * s.ndl * 0.15);
}

entries.matcap:
@fragment fn fs_matcap(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy);
    // a procedural matcap: the view-space normal indexes a lit disc with a moving highlight
    let m = s.n.xy; let hl = normalize(vec2f(u.lx, u.ly) + vec2f(1e-4)) * 0.55 * min(length(vec2f(u.lx, u.ly)), 1.0);
    let d = length(m - hl); let ring = 0.5 + 0.5 * cos(length(m) * mix(4.0, 16.0, u.k.x));
    let c = mix(srgb_to_linear(u.ink.rgb), albedo(), 0.5 + 0.5 * m.y) + srgb_to_linear(u.cream.rgb) * (exp(-d * d * 12.0) + ring * 0.12 * u.k.y);
    return out(s, c);
}

entries.hatching:
@fragment fn fs_hatching(@builtin(position) fp: vec4f) -> @location(0) vec4f {
    let s = setup(fp.xy); let px = fp.xy / u.pixelScale; let sc = mix(3.0, 8.0, u.k.x);
    let shade_ = 1.0 - s.ndl;   // darkness → more hatch layers, like a tonal art map
    var h = 0.0;
    h += step(0.7, fract((px.x + px.y) / sc)) * step(0.2, shade_);
    h += step(0.7, fract((px.x - px.y) / sc)) * step(0.45, shade_);
    h += step(0.7, fract(px.x / sc)) * step(0.7, shade_);
    h += step(0.7, fract(px.y / sc)) * step(0.85, shade_);
    let paper = srgb_to_linear(u.cream.rgb); let ink = srgb_to_linear(u.ink.rgb);
    return out(s, mix(paper, ink, clamp(h, 0.0, 1.0) * mix(0.6, 1.0, u.k.y)));
}

glass.core:
// Orb shader pack. WGSL, WebGPU.
// Derived from the Metal shaders of the MIT-licensed "murmur" package
// (c) Kris Puckett; ported function-for-function. MIT notice retained.
const M_PI_F: f32 = 3.14159265358979;

fn mh_hash(v: vec3u) -> u32 {
    var h: u32 = ((v.x * 1597334673u) ^ (v.y * 3812015801u)) ^ (v.z * 2798796415u);
    h ^= h >> 15u;
    h *= 2246822519u;
    h ^= h >> 13u;
    h *= 3266489917u;
    h ^= h >> 16u;
    return h;
}

fn mh_grad3(c: vec3i) -> vec3f {
    var h: u32 = mh_hash(vec3u(c + 4096));
    var z: f32 = fma(f32(h & 0xFFFFu), 2.0 / 65535.0, -1.0);
    var a: f32 = f32((h >> 16u) & 0xFFFFu) * (6.28318530718 / 65536.0);
    var r: f32 = sqrt(max(0.0, 1.0 - (z * z)));
    return vec3f(r * cos(a), r * sin(a), z);
}

fn mh_noise3(p: vec3f) -> f32 {
    var i: vec3f = floor(p);
    var f: vec3f = p - i;
    var u: vec3f = ((f * f) * f) * ((f * ((f * 6.0) - 15.0)) + 10.0);
    var c: vec3i = vec3i(i);
    var va: f32 = dot(mh_grad3(c + vec3i(0, 0, 0)), f - vec3f(0.0, 0.0, 0.0));
    var vb: f32 = dot(mh_grad3(c + vec3i(1, 0, 0)), f - vec3f(1.0, 0.0, 0.0));
    var vc: f32 = dot(mh_grad3(c + vec3i(0, 1, 0)), f - vec3f(0.0, 1.0, 0.0));
    var vd: f32 = dot(mh_grad3(c + vec3i(1, 1, 0)), f - vec3f(1.0, 1.0, 0.0));
    var ve: f32 = dot(mh_grad3(c + vec3i(0, 0, 1)), f - vec3f(0.0, 0.0, 1.0));
    var vf: f32 = dot(mh_grad3(c + vec3i(1, 0, 1)), f - vec3f(1.0, 0.0, 1.0));
    var vg: f32 = dot(mh_grad3(c + vec3i(0, 1, 1)), f - vec3f(0.0, 1.0, 1.0));
    var vh: f32 = dot(mh_grad3(c + vec3i(1, 1, 1)), f - vec3f(1.0, 1.0, 1.0));
    return mix(mix(mix(va, vb, u.x), mix(vc, vd, u.x), u.y), mix(mix(ve, vf, u.x), mix(vg, vh, u.x), u.y), u.z);
}

fn mh_srgb_to_linear(c: vec3f) -> vec3f {
    var c_p: vec3f = c;
    c_p = max(c_p, vec3f(0.0));
    return select(c_p * (1.0 / 12.92), pow((c_p + 0.055) * (1.0 / 1.055), vec3f(2.4)), c_p > vec3f(0.04045));
}

fn mh_linear_to_srgb(c: vec3f) -> vec3f {
    var c_p: vec3f = c;
    c_p = max(c_p, vec3f(0.0));
    return select(c_p * 12.92, (1.055 * pow(c_p, vec3f(1.0 / 2.4))) - 0.055, c_p > vec3f(0.0031308));
}

fn mh_linear_to_oklab(c: vec3f) -> vec3f {
    var l: f32 = ((0.4122214708 * c.r) + (0.5363325363 * c.g)) + (0.0514459929 * c.b);
    var m: f32 = ((0.2119034982 * c.r) + (0.6806995451 * c.g)) + (0.1073969566 * c.b);
    var s: f32 = ((0.0883024619 * c.r) + (0.2817188376 * c.g)) + (0.6299787005 * c.b);
    var l_: f32 = pow(max(l, 0.0), 1.0 / 3.0);
    var m_: f32 = pow(max(m, 0.0), 1.0 / 3.0);
    var s_: f32 = pow(max(s, 0.0), 1.0 / 3.0);
    return vec3f(((0.2104542553 * l_) + (0.7936177850 * m_)) - (0.0040720468 * s_), ((1.9779984951 * l_) - (2.4285922050 * m_)) + (0.4505937099 * s_), ((0.0259040371 * l_) + (0.7827717662 * m_)) - (0.8086757660 * s_));
}

fn mh_oklab_to_linear(lab: vec3f) -> vec3f {
    var l_: f32 = (lab.x + (0.3963377774 * lab.y)) + (0.2158037573 * lab.z);
    var m_: f32 = (lab.x - (0.1055613458 * lab.y)) - (0.0638541728 * lab.z);
    var s_: f32 = (lab.x - (0.0894841775 * lab.y)) - (1.2914855480 * lab.z);
    var l: f32 = (l_ * l_) * l_;
    var m: f32 = (m_ * m_) * m_;
    var s: f32 = (s_ * s_) * s_;
    return vec3f(((4.0767416621 * l) - (3.3077115913 * m)) + (0.2309699292 * s), ((-1.2684380046 * l) + (2.6097574011 * m)) - (0.3413193965 * s), ((-0.0041960863 * l) - (0.7034186147 * m)) + (1.7076147010 * s));
}

fn mh_lch(L: f32, C: f32, h: f32) -> vec3f {
    return vec3f(L, C * cos(h), C * sin(h));
}

fn mh_paper(inkColor: vec4f) -> f32 {
    var L: f32 = mh_linear_to_oklab(mh_srgb_to_linear(vec3f(inkColor.rgb))).x;
    return smoothstep(0.50, 0.72, L);
}

struct MHPalette {
    s0: vec3f,
    s1: vec3f,
    s2: vec3f,
    s3: vec3f,
    paper: f32,
    duo: f32,
    dHue: f32,
    dC: f32,
    dL: f32
}

fn mh_palette(inkColor: vec4f, toneColor: vec4f, tone2Color: vec4f, hueShift: f32, depth: f32) -> MHPalette {
    var ink: vec3f = mh_linear_to_oklab(mh_srgb_to_linear(vec3f(inkColor.rgb)));
    var tone: vec3f = mh_linear_to_oklab(mh_srgb_to_linear(vec3f(toneColor.rgb)));
    var L: f32 = tone.x;
    var C: f32 = length(tone.yz);
    var h: f32 = atan2(tone.z, tone.y) + hueShift;
    var d: f32 = clamp(depth, 0.30, 2.00);
    var p: MHPalette;
    p.paper = mh_paper(inkColor);
    var tone2: vec3f = mh_linear_to_oklab(mh_srgb_to_linear(vec3f(tone2Color.rgb)));
    var C2: f32 = length(tone2.yz);
    var h2: f32 = atan2(tone2.z, tone2.y) + hueShift;
    var dh: f32 = h2 - (atan2(tone.z, tone.y) + hueShift);
    p.dHue = dh - (6.2831853 * floor((dh / 6.2831853) + 0.5));
    p.dC = C2 / max(length(tone.yz), 1e-4);
    p.dL = tone2.x / max(tone.x, 1e-4);
    p.duo = smoothstep(0.004, 0.035, length(tone2 - tone));
    var d0: vec3f = ink;
    var d1: vec3f = mh_lch(mix(ink.x, L, 0.30 / d), C * (0.52 + (0.10 * d)), h - 0.35);
    var d2: vec3f = mh_lch(L, C, h);
    var d3: vec3f = mh_lch(min(L * (1.20 + (0.12 * d)), 0.93), C * 0.55, h + 0.10);
    var Lp: f32 = ink.x;
    var l0: vec3f = ink;
    var l1: vec3f = mh_lch(mix(Lp, L, 0.42 / d), C * (0.34 + (0.10 * d)), h + 0.05);
    var l2: vec3f = mh_lch(L * (0.82 - (0.06 * d)), C * (1.20 + (0.14 * d)), h);
    var l3: vec3f = mh_lch(max(L * (0.52 - (0.05 * d)), 0.18), C * (1.05 + (0.10 * d)), h - 0.08);
    p.s0 = mix(d0, l0, p.paper);
    p.s1 = mix(d1, l1, p.paper);
    p.s2 = mix(d2, l2, p.paper);
    p.s3 = mix(d3, l3, p.paper);
    return p;
}

const MH_SPREAD: f32 = 0.50;

fn mh_shade(p: MHPalette, t: f32, hue: f32) -> vec3f {
    var t_p: f32 = t;
    t_p = clamp(t_p, 0.0, 1.0);
    var lab: vec3f;
    if (t_p < 0.40) {
        lab = mix(p.s0, p.s1, smoothstep(0.0, 1.0, t_p * 2.5));
    } else if (t_p < 0.78) {
        lab = mix(p.s1, p.s2, smoothstep(0.0, 1.0, (t_p - 0.40) * (1.0 / 0.38)));
    } else {
        lab = mix(p.s2, p.s3, smoothstep(0.0, 1.0, (t_p - 0.78) * (1.0 / 0.22)));
    }
    var a: f32 = hue * (1.0 / MH_SPREAD);
    var pos: f32 = max(a, 0.0);
    var neg: f32 = max(-a, 0.0);
    var rot: f32 = (-neg * MH_SPREAD) + (pos * mix(MH_SPREAD, p.dHue, p.duo));
    var w: f32 = min(pos, 1.0) * p.duo;
    var cS: f32 = 1.0 + (w * (p.dC - 1.0));
    var lS: f32 = 1.0 + (w * (p.dL - 1.0));
    var ch: f32 = cos(rot);
    var sh: f32 = sin(rot);
    { let _sw1 = vec2f((lab.y * ch) - (lab.z * sh), (lab.y * sh) + (lab.z * ch)) * cS;
      lab.y = _sw1.x;
      lab.z = _sw1.y;
    }
    lab.x *= lS;
    return mh_oklab_to_linear(lab);
}

fn mh_out(linearRGB: vec3f, pixel: vec2f) -> vec4f {
    var c: vec3f = mh_linear_to_srgb(linearRGB);
