    o.keyLo = mix(0.72, 0.26, m);
    o.keyHi = mix(0.40, 0.98, m);
    o.keyBLo = mix(0.66, 0.44, m);
    o.keyBHi = mix(0.34, 0.60, m);
    o.coreLo = mix(0.88, 0.60, m);
